import java.util.Map;

public class ClassX {
    /**
     * Validates the token header to ensuring the algorithm is supported.
     * 
     * The function checks if the 'alg' field in the header contains 'HS256'.
     */
    public void validateTokenHeader(Map<String, String> headers) {
        // Check if the 'alg' field exists in the headers
        if (headers.containsKey("alg")) {
            // Get the value of the 'alg' field
            String alg = headers.get("alg");

            // Check if the algorithm is 'HS256'
            if ("HS256".equalsIgnoreCase(alg)) {
                System.out.println("Algorithm is supported: HS256");
            } else {
                System.out.println("Unsupported algorithm: " + alg);
                throw new IllegalArgumentException("Unsupported algorithm for token verification.");
            }
        } else {
            System.out.println("Algorithm not found in header.");
            throw new IllegalArgumentException("Algorithm not specified in token header.");
        }
    }
}

