        this.header = header;
    }

    public boolean isTokenAlgorithmSupported() {
        if (header.containsKey("alg") && "HS256".equals(header.get("alg"))) {
            return true;
        }
        return false;
    }

    // Getter for debugging or other purposes
    public Map<String, String> getHeader() {
        return header;
    }
}
