    public static boolean validateAlgorithm(String header) {
        // Assume that the header is a JSON Web Token (JWT)
        // Parse the header to extract the 'alg' field
        try {
            Map<String, String> headers = new HashMap<>();
            // Split the header string by commas and spaces to get individual key-value pairs
            String[] parts = header.split(",");
            for (int i = 0; i < parts.length; i++) {
                String part = parts[i].trim();
                int equalsIndex = part.indexOf('=');
                if (equalsIndex != -1) {
                    String key = part.substring(0, equalsIndex).trim();
                    String value = part.substring(equalsIndex + 1).trim().replace("\"", ""); // Remove quotes
                    headers.put(key, value);
                }
            }
            // Check if 'alg' is present in the headers and is 'HS256'
            if (headers.containsKey("alg") && "HS256".equals(headers.get("alg"))) {
                return true;
            }
        } catch (Exception e) {
            // Handle any parsing errors
            e.printStackTrace();
        }
        return false;
    }

