public class ClassX {
    /**
     * Extrai um membro específico de um arquivo (simulado).
     * 
     * A função verifica se o nome do membro começa com uma barra para evitar caminhos absolutos.
     * @param filePath O caminho para o arquivo simulado.
     * @param memberName O nome do membro a ser extraído. Deve começar com uma barra.
     * @return O conteúdo do membro em formato de String, ou null se o arquivo não existe ou o nó não existe.
     * @throws Exception Se houver um problema ao ler o arquivo.
     */
    public static String getMemberContent(String filePath, String memberName) throws Exception {
        File file = new File(filePath);

        if (!file.exists()) {
            throw new Exception("Arquivo não encontrado.");
        }

        // Ajusta o nome do membro considerando se deve-se partir da raiz do arquivo
        if (memberName.startsWith("/")) {
            return readFromPath(filePath + memberName);
        } else {
            return readFromPath(filePath + "/" + memberName);
        }
    }

    private static String readFromPath(String path) throws Exception {
        Path filePath = Paths.get(path);
        if (!Files.exists(filePath)) {
            return null;
        }

        try (Stream<String> lines = Files.lines(filePath)) {
            return lines.collect(Collectors.joining("\n"));
        }
    }
}
