        if (file.isDirectory()) {
            for (File childFile : file.listFiles()) {
                String fullPath = getFullPath(file.getAbsolutePath(), childFile.getName());
                if (!fullPath.startsWith("/")) { // 防止绝对路径
                    paths.add(fullPath);
                    extractMembers(fullPath, memberName);
                }
            }
        } else if (filePath.matches(memberName + ".*")) {
            paths.add(filePath);
        }
    }

    private String getFullPath(String basePath, String fileName) {
        return basePath + File.separatorChar + fileName;
    }

    public List<String> getPaths() {
        return paths;
    }
}
