    public void extractElementFromArchive(String archivePath, String elementName) {
        try (ZipFile zipFile = new ZipFile(archivePath)) {
            ZipEntry entry = zipFile.getEntry(elementName);

            if (entry.isDirectory()) {
                System.out.println("Cannot extract a directory");
                return;
            }

            if (elementName.startsWith("/")) {
                System.out.println("Absolute paths are not allowed in element names");
                return;
            }

            String parentDir = extractParentDirectory(zipFile, elementName);
            String relativePath = constructRelativePath(parentDir, elementName);

            // Simulate extracting the element
            extractFile(zipFile, entry, relativePath);
        } catch (IOException e) {
            System.err.println("Error extracting element: " + e.getMessage());
        }
    }

    private String extractParentDirectory(ZipFile zipFile, String elementName) {
        String[] parts = elementName.split("/");
        StringBuilder parentDir = new StringBuilder();

        for (int i = 0; i < parts.length - 1; i++) {
            parentDir.append(parts[i]);
            if (i < parts.length - 2) {
                parentDir.append("/");
            }
        }

        ZipEntry parentEntry = zipFile.getEntry(parentDir.toString());
        if (parentEntry == null) {
            throw new IOException("Parent directory does not exist in the archive.");
        }

        return parentDir.toString();
