        String[] elementParts = elementName.split("/");

        for (int i = 0; elementsParts.length > i && parentParts.length > i; i++) {
            if (!elementsParts[i].equals(parentParts[i])) {
                break;
            }
        }

        StringBuilder relativePath = new StringBuilder();
        for (int i = elementsParts.length; i < elementParts.length; i++) {
            relativePath.append(elementParts[i]).append("/");
        }

        return relativePath.toString();
    }

