            int length;
            while ((length = inputStream.read(buffer)) > 0) {
                outputStream.write(buffer, 0, length);
            }

            System.out.println("Successfully extracted: " + relativePath);
        } catch (IOException e) {
            System.err.println("Error extracting file: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        ArchiveExtractor extractor = new ArchiveExtractor();
        extractor.extractElementFromArchive("archive.zip", "/folder/subfolder/file.txt");
    }
