public class ClassX {
    public File extractEntryFromZip(String zipFilePath, String entryName) throws IOException {
        ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath));
        ZipEntry nextEntry = zis.getNextEntry();

        while (nextEntry != null) {
            if (entryName.startsWith("/") || (nextEntry.getName().equals(entryName))) {
                File tempFile = new File(System.getProperty("java.io.tmpdir") + "/" + nextEntry.getName());
                FileOutputStream fos = new FileOutputStream(tempFile);

                byte[] bytesIn = new byte[1024];
                int read;

                while ((read = zis.read(bytesIn)) != -1) {
                    fos.write(bytesIn, 0, read);
                }

                fos.close();
                return tempFile;
            }
            zis.closeEntry();
            nextEntry = zis.getNextEntry();
        }
        return null; // Entry not found or is a directory
    }
}
