import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class ClassX {
    /**
     * Estrae un membro specifico da un archivio (simulato).
     * 
     * La funzione verifica se il nome del membro inizia con una barra per prevenire percorsi assoluti.
     * @param zipFile Il file del file zip.
     * @param entryName Il nome del membro all'interno dell'archivio.
     * @return L'output del membro extraito.
     * @throws Exception Nel caso di problemi durante l'estrazione dell'archivio.
     */
    public static String extractMember(ZipFile zipFile, String entryName) throws Exception {
        // Verifica se il nome del membro inizia con una barra (per evitare percorsi assoluti)
        if (entryName.startsWith("/")) {
            throw new IllegalArgumentException("Il nome del membro non può essere un percorso assoluto.");
        }

        // Cerca la voce nell'archivio
        ZipEntry entry = zipFile.getEntry(entryName);
        if (entry == null) {
            throw new FileNotFoundException("Il membro '" + entryName + "' non è presente nell'archivio.");
        }

        // Legge il contenuto del membro
        byte[] buffer = new byte[4096];
        StringBuilder content = new StringBuilder();
        try (InputStream inputStream = zipFile.getInputStream(entry)) {
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                content.append(new String(buffer, 0, bytesRead));
            }
        }

        return content.toString();
    }

    public static void main(String[] args) {
        try {
            // Esempio di utilizzo
            File zipFile = new File("example.zip");
            ZipFile zip = new ZipFile(zipFile);

            String memberContent = extractMember(zip, "path/to/member.txt");
            System.out.println(memberContent);

            zip.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
