import java.io.File;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

public class ClassX {
    /**
     * Extrait un membre spécifique d'une archive (simulé).
     * 
     * La fonction vérifie si le nom du membre commence par un slash pour empêcher les chemins absolus.
     * @param zipFilePath Chemin complet vers l'archive ZIP.
     * @param entryName Nom du membre à extraire, sans chemin absolut.
     * @return Le fichier extrait ou null si la décompression a échoué.
     */
    public static File extractMember(String zipFilePath, String entryName) {
        if (entryName.startsWith("/")) {
            throw new IllegalArgumentException("Le nom de membre doit être relatif");
        }

        try (ZipFile zipFile = new ZipFile(zipFilePath)) {
            ZipEntry entry = zipFile.getEntry(entryName);
            if (entry == null) {
                throw new FileNotFoundException("Le membre n'existe pas dans l'archive");
            }

            File targetDirectory = new File("extracted");
            if (!targetDirectory.exists()) {
                targetDirectory.mkdirs();
            }

            File destinationFile = new File(targetDirectory, entry.getName());
            Files.copy(zipFile.getInputStream(entry), destinationFile.toPath(), StandardCopyOption.REPLACE_EXISTING);

            return destinationFile;
        } catch (IOException e) {
            System.err.println("Échec de la décompression: " + e.getMessage());
            return null;
        }
    }
}
```

