            File[] filteredArchives = dir.listFiles((file) -> file.getName().startsWith(prefix));

            // Filtri loetavamise ja tagasisideväärtuse tagastamise
            if (filteredArchives != null && filteredArchives.length > 0) {
                StringBuffer sb = new StringBuffer();
                for (File archive : filteredArchives) {
                    sb.append(archive.getName()).append(",");
                }
                return sb.toString().split(",");
            }
            return new String[0];
        }
    }
