import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Εξάγει ένα συγκεκριμένο μέλος από ένα αρχείο (προσομοίωση).
     * 
     * Η συνάρτηση ελέγχει αν το όνομα του μέλους αρχίζει με μια κάθετο για να αποτρέψει απόλυτες διαδρομές.
     * 
     * @param filename Ο όνομα του αρχείου που θα αναλύσει
     * @param prefix Το πρόfix του ονόματος μέλουs για την ανάλυσή των γραμμών του αρχείου
     * @return Ενα πίνακα με τις εξαγόμενες γραμμές
     */
    public String[] extractMembersByPrefix(String filename, char prefix) {
        // Initialize a list to hold the extracted members
        java.util.ArrayList<String> members = new java.util.ArrayList<>();

        // Regular expression to match lines starting with the specified prefix
        Pattern pattern = Pattern.compile("^" + Pattern.quote(String.valueOf(prefix)) + "\\w*");

        try (BufferedReader br = new BufferedReader(new FileReader(filename))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (pattern.matcher(line).matches()) {
                    members.add(line);
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        // Convert the list to an array and return it
        return members.toArray(new String[0]);
    }
}
```

### Explanation:
