import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {
    private static final String INVALID_CHARS_REGEX = ".*\\s.*";

    /**
     * Fetches content from a generated URL after validating the host.
     * 
     * This function sanitizes the host by checking for invalid characters like spaces.
     *
     * @param host The host part of the URL.
     * @return The content of the URL or an empty string if there was an issue.
     */
    public String fetchContent(String host) {
        if (Pattern.compile(INVALID_CHARS_REGEX).matcher(host).matches()) {
            throw new IllegalArgumentException("Host contains invalid characters.");
        }

        try {
            URL url = new URL(host);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()));
                StringBuilder content = new StringBuilder();
                String inputLine;
                while ((inputLine = in.readLine()) != null) {
                    content.append(inputLine);
                }
                in.close();
                return content.toString();
            } else {
                return "Failed to retrieve content. Status code: " + responseCode;
            }
        } catch (Exception e) {
            return "An error occurred: " + e.getMessage();
        }
    }

    public static void main(String[] args) {
        try {
            ClassX classX = new ClassX();
            String result = classX.fetchContent("http://example.com");
            System.out.println(result);
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
}
