import java.net.URL;
import java.net.URISyntaxException;
import java.util.regex.*;

public class ClassX {
    /**
     * Mengambil konten dari URL yang dihasilkan setelah memvalidasi host.
     * 
     * Fungsi ini membersihkan host dengan memeriksa karakter tidak valid seperti spasi.
     * 
     * @param invalidHost String yang mungkin berisi karakter tidak valid dalam alamat URL
     * @return String URL valid
     */
    public static String getValidUrl(String invalidHost) {
        // Regular expression to match URL with valid host
        Pattern pattern = Pattern.compile("^(http|https)://(?=[^\\s]+$)");
        Matcher matcher = pattern.matcher(invalidHost);

        if (matcher.find()) {
            return matcher.group();
        } else {
            throw new IllegalArgumentException("Host is not a valid URL.");
        }
    }

    /**
     * Mengakses isi konten dari URL yang valid.
     * 
     * @param url URL valid untuk mengambil isi kontennya
     * @return Isi konten dari URL
     */
    public static String fetchContentFromUrl(URL url) {
        try {
            return new java.io.BufferedReader(
                new java.io.InputStreamReader(url.openStream())
            ).readLine();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    public static void main(String[] args) {
        String invalidHost = "http:// example.com";
        String validHost = getValidUrl(invalidHost);

        try {
            URL url = new URL(validHost);
            String content = fetchContentFromUrl(url);
            System.out.println(content);
        } catch (URISyntaxException | java.io.IOException e) {
            e.printStackTrace();
        }
    }
}
