import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.util.regex.Pattern;

public class ClassX {
    private static final Pattern VALID_HOST_PATTERN = Pattern.compile("^[a-zA-Z0-9-]+(\\.[a-zA-Z0-9-]+)*$");

    /**
     * Mengambil konten dari URL yang dihasilkan setelah memvalidasi host.
     * 
     * Fungsi ini membersihkan host dengan memeriksa karakter tidak valid seperti spasi.
     * 
     * @param urlString URL yang akan diperiksa dan digunakan untuk fetching data
     * @return Konten dari URL jika host valid, null jika host tidak valid
     */
    public HttpResponse<String> fetchContent(String urlString) {
        try {
            URI uri = new URI(urlString);
            String validatedHost = validateHost(uri.getHost());
            if (validatedHost == null) {
                return null; // Return null if host is invalid
            }

            URL url = new URL("http://" + validatedHost + uri.getPath() + "?" + uri.getQuery());
            HttpClient client = HttpClient.newHttpClient();
            HttpRequest request = HttpRequest.newBuilder()
                    .uri(url.toURI())
                    .header("accept", "application/json")
                    .build();

            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
            return response;
        } catch (URISyntaxException | IllegalArgumentException e) {
            System.out.println("Invalid URL or host: " + e.getMessage());
            return null;
        }
    }

    /**
     * Memeriksa dan mengembalikan host setelah dihapus spasi.
     * 
     * Host yang memiliki karakter lain selain alfabet dan angka ditandai dengan tanda minus (-).
     * 
