import java.net.MalformedURLException;
import java.net.URL;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    /**
     * Kumuha ng nilalaman mula sa isang nabuo na URL pagkatapos i-validate ang host.
     * 
     * Ang function na ito ay naglilinis ng host sa pamamagitan ng pag-check para sa mga hindi wastong karakter tulad ng mga espasyo.
     * 
     * @param urlString String URL string
     * @return The parsed URL object or null if the string cannot be parsed as a valid URL
     * @throws MalformedURLException If the URL is malformed
     */
    public static String getHost(String urlString) throws MalformedURLException {
        // Create a URL object from the given URL string
        URL url = new URL(urlString);

        // Use a regular expression to validate the host name
        String hostPattern = "^\\w+(\\.\\w+)*$";
        Pattern pattern = Pattern.compile(hostPattern);
        Matcher matcher = pattern.matcher(url.getHost());

        // Return the host only if it matches the pattern
        if (matcher.matches()) {
            return url.getHost();
        } else {
            throw new MalformedURLException("Invalid hostname: " + url.getHost());
        }
    }

    public static void main(String[] args) {
