            System.out.println(getHost("https://sub.example.net")); // Output: sub.example.net
            System.out.println(getHost("ftp://ftp.example.org")); // Output: ftp.example.org
            System.out.println(getHost("http://invalid..host.com")); // Throws MalformedURLException
        } catch (MalformedURLException e) {
