import java.net.URL;

public class ClassX {
    /**
     * Kumuha ng nilalaman mula sa isang nabuo na URL pagkatapos i-validate ang host.
     * 
     * Ang function na ito ay naglilinis ng host sa pamamagitan ng pag-check para sa mga hindi wastong karakter tulad ng mga espasyo.
     */
    public static String getValidHost(URL url) throws MalformedURLException {
        String host = url.getHost();

        // Ivalidate ang host para sa mga tanong kung ang karakter na sinasabi ay mayroong mga hindi wastong pangalan
        while (host.indexOf('\u0020') != -1 || // Espacio
               host.indexOf('\n') != -1 ||   // Salita
               host.indexOf('\r') != -1 ||   // Karoon
               host.indexOf('\t') != -1 ||   // Tab
               host.indexOf('#') != -1 ||   // Hash
               host.indexOf('%') != -1 ||   // Percent sign
               host.indexOf('&') != -1 ||   // Ampersand
               host.indexOf(':') != -1 ||   // Colon
               host.indexOf('/') != -1 ||   // Forward slash
               host.indexOf('<') != -1 ||   // Less than
               host.indexOf('>') != -1 ||   // Greater than
               host.indexOf('"') != -1 ||   // Double quotes
               host.indexOf('|') != -1 ||   // Vertical bar
               host.indexOf('?') != -1 ||   // Question mark
               host.indexOf('{') != -1 ||   // Curly brace left
               host.indexOf('}') != -1 ||   // Curly brace right
               host.indexOf('[') != -1 ||   // Square bracket left
               host.indexOf(']') != -1 ||   // Square bracket right) {
            throw new IllegalArgumentException("Invalid host: " + host);
        }

        return host;
    }

    public static void main(String[] args) {
        try {
            URL url = new URL("http://example.com/some/path?query=123");
            String validHost = getValidHost(url);
            System.out.println("Valid Host: " + validHost);
        } catch (MalformedURLException | IllegalArgumentException e) {
            e.printStackTrace();
        }
    }
}
