import java.net.HttpURLConnection;
import java.net.URL;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Haal inhoud op van een gegenereerde URL na het valideren van de host.
     * 
     * Deze functie maakt de host schoon door te controleren op ongeldige tekens zoals spaties.
     */
    public static String fetchUrlContent(String urlString, boolean isValidHost) {
        // Controlleer of de host is valide
        if (!isValidHost) {
            System.out.println("Host is niet geldig.");
            return null;
        }

        try {
            URL url = new URL(urlString);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.connect();

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                return new String(connection.getInputStream().readAllBytes());
            } else {
                System.out.println("Kon geen bestand ophalen met http status: " + responseCode);
                return null;
            }
        } catch (Exception e) {
            System.out.println("Fout bij het ophalen van de URL: " + e.getMessage());
            return null;
        }
    }

    public static void main(String[] args) {
        String urlString = "http://example.com";
        boolean isValidHost = validateHost(urlString);

        String content = fetchUrlContent(urlString, isValidHost);
        if (content != null) {
            System.out.println(content);
        }
    }

    private static boolean validateHost(String urlString) {
        String validHostRegex = "^[a-zA-Z0-9-.]+$";
        Pattern pattern = Pattern.compile(validHostRegex);
        return pattern.matcher(urlString).matches();
    }
}
