        try {
            // URL'nin oluşturulması
            URL url = new URL(urlString);

            // HTTP bağlantısının oluşturulması
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");
            conn.setRequestProperty("User-Agent", "Mozilla/5.0");

            // Bağlantı sonucunun kontrol edilmesi
            if (conn.getResponseCode() != 200) {
                throw new RuntimeException("Could not connect to the server.");
            }

            // InputStream'dan veriyi okumaya başlama
            BufferedReader in = new BufferedReader(new InputStreamReader(conn.getInputStream(), StandardCharsets.UTF_8));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = in.readLine()) != null) {
                content.append(line).append("\n");
            }
            in.close();

            // Ana bilgisayarın doğrulandığını ve kurlari temizledikten sonraki içeriği getiriyoruz
            return cleanContentForHost(content.toString());
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
