public class ClassX {
    /**
     * Récupère le contenu d'une URL générée après avoir validé l'hôte.
     * 
     * Cette fonction assainit l'hôte en vérifiant la présence de caractères invalides tels que des espaces.
     * 
     * @param urlString l'URL à partir de laquelle extraire le contenu
     * @return Le contenu de l'URL, ou null si une erreur se produit
     */
    public static String getURLContent(String urlString) {
        try {
            // Créer l'URL à partir de la chaîne de caractères
            URL url = new URL(urlString);
            // Sanitizer l'hôte
            String sanitizedHost = sanitizeHost(url.getHost());

            // Construct the complete URL with sanitized host
            url = new URL(sanitizedHost);

            // Créer une connexion HTTP
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.setUseCaches(false);
            connection.connect();

            // Vérifier la réponse HTTP
            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                return null; // Retourner null si la réponse n'est pas OK
            }

            // Lire le contenu de la réponse
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
            }
            reader.close();

            return content.toString();
        } catch (Exception e) {
            e.printStackTrace();
            return null; // Retourner null en cas d'erreur
        }
