        String line;
        while ((line = reader.readLine()) != null) {
            contentBuilder.append(line).append("\n");
        }

        // Cerrar los streams
        reader.close();
        inputStream.close();

        return contentBuilder.toString();
    }

    public static void main(String[] args) {
