    private String sanitizeHost(String hostEl) {
        // Verificar si el host está vacío o solo contiene espacios
        if (hostEl == null || hostEl.trim().isEmpty()) {
            return null;
        }

        // Reemplazar espacios por puntos
        hostEl = hostEl.replace(" ", ".");

        return hostEl;
    }

    /**
     * Obtiene contenido de una URL generada después de validar el host.
     * 
     * @param hostEl string con el nombre del host que será sanitizado antes de la validación.
     * @param protocolEl string con el protocolo usado para la URL.
