     * @return un URL si éste está correctamente generado y validado, null en caso contrario.
     */
    public URL buildHttpUrl(String hostEl, String protocolEl, int port, String pathEl) {
        // Sanitizar el host
        String sanitizedHost = sanitizeHost(hostEl);
        if (sanitizedHost == null) {
            return null;
        }

        // Construir la URL
        try {
            URL url = new URL(protocolEl, sanitizedHost, port, pathEl);
            return url;
        } catch (Exception e) {
            return null;
        }
    }
}
