            if (url.getHost() == null) {
                throw new MalformedURLException("Invalid URL");
            }

            // Очищаем хост URL от недопустимых символов
            String cleanHost = url.getHost().replaceAll("[^a-zA-Z0-9_.]", "");

            // Если хост не изменен, URL невалиден
            if (cleanHost.equals(url.getHost())) {
                throw new IllegalArgumentException("Invalid host");
            }

            // Собираем новый URL с отчищенным хостом
            StringBuilder newUrl = new StringBuilder();
            newUrl.append(url.getProtocol()).append("://");
            newUrl.append(cleanHost);
            if (url.getPort() != -1) {
                newUrl.append(":").append(url.getPort());
