import java.net.URL;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Ruft Inhalte von einer generierten URL ab, nachdem der Host validiert wurde.
     * 
     * Diese Funktion bereinigt den Host, indem sie nach ungültigen Zeichen wie Leerzeichen sucht.
     */
    public String retrieveContent(String urlString) throws MalformedURLException {
        URL url = new URL(urlString);
        String host = url.getHost();

        // Erstellen eines regulären Ausdrucks, der ungültige Zeichen enthält (leerzeichen und Punkte)
        Pattern pattern = Pattern.compile("[\\s.]");
        Matcher matcher = pattern.matcher(host);

        // Ersetzen der ungültigenZeichen durch einen Pflock
        String cleanedHost = matcher.replaceAll("_");

        // Bauen von URL neu, damit der Host gültig ist
        URL validUrl = new URL("http://" + cleanedHost + url.getFile());

        // Abruf des Inhalts der URL
        String content = "";
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(validUrl.openStream()))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
            content = sb.toString().trim();
        } catch (IOException e) {
            e.printStackTrace();
        }

        return content;
    }
}
