     */
    public String fetchDataFromURL(String hostname, String path) throws MalformedURLException {
        // Controllo se l'host contiene caratteri non validi (spazi)
        if (hostname.contains(" ")) {
            throw new IllegalArgumentException("Host name must not contain spaces.");
        }

        // Crea l'URL con l'host sanitizzato
        URL url = new URL("http://" + hostname + "/" + path);

        // Implementa l'algoritmo specificato per recupere i dati da URL
        // Nell'esempio seguente, utilizzeremo HTTP e leggeremo il contenuto all'interno di un ByteArrayOutputStream
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        try (java.net.HttpURLConnection conn = (java.net.HttpURLConnection) url.openConnection()) {
            conn.setDoOutput(true);
            conn.setRequestProperty("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8");

            try (java.io.InputStream in = conn.getInputStream()) {
                byte[] buffer = new byte[1024];
                int read;
                while ((read = in.read(buffer)) != -1) {
                    baos.write(buffer, 0, read);
                }
            }
        }

        // Restituisce i dati letto come stringa
        return baos.toString();
    }
}
