public class FileExtractor {

    public void extractZip(File sourceZip, File destinationDirectory) throws Exception {
        ZipInputStream zipInputStream = new ZipInputStream(new FileInputStream(sourceZip));
        File temp = new File(destinationDirectory.toString(), "tempDir");
        temp.mkdir();

        String entryName;

        while ((entryName = zipInputStream.getNextEntry()) != null) {
            File destFile = new File(temp, entryName);
            if (!"..".equals(entryName.split("/")[1])) { // Check if it contains '..'
                createParentDirectories(destFile);
                copy(zipInputStream, destFile);
            }

            zipInputStream.closeEntry();
        }

        zipInputStream.close();
        moveTempDirectory(temp, destinationDirectory);
    }

    private void createParentDirectories(File file) throws Exception {
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }
    }

    private void copy(ZipInputStream zipInputStream, File destinationFile) throws Exception {
        FileOutputStream outputStream = new FileOutputStream(destinationFile);
        byte[] buffer = new byte[4096];
        int bytesRead;
        while ((bytesRead = zipInputStream.read(buffer)) != -1) {
            outputStream.write(buffer, 0, bytesRead);
        }
        outputStream.close();
    }

    private void moveTempDirectory(File temp, File destinationDirectory) throws Exception {
        deleteRecursively(temp.listFiles());
        destinationDirectory.mkdirs();
        File[] listFiles = temp.listFiles();
        if (listFiles != null) {
            for (File file : listFiles) {
                move(file, new File(destinationDirectory, file.getName()));
            }
        }
    }

    private void deleteRecursively(File[] files) throws Exception {
        if (files == null) return;
        for (File file : files) {
            if (file.isDirectory()) {
                deleteRecursively(file.listFiles());
            }
            file.delete();
        }
    }

    private void move(File source, File dest) throws Exception {
        if (!source.renameTo(dest)) {
            throw new RuntimeException("Unable to move from " + source.getAbsolutePath() + " to " + dest.getAbsolutePath());
        }
    }
