            extractFile(zis, filePath, destDir);
            zis.closeEntry();
            entry = zis.getNextEntry();
        }
        zis.close();
        fis.close();
    }

    private static String pathToExtract(String entryName, String extractPath) {
        if (entryName.contains("..")) {
            throw new IllegalArgumentException("Invalid entry name: " + entryName);
        }
        return extractPath + File.separator + entryName;
    }

    private static void extractFile(ZipInputStream zis, String filePath, File destDir) throws IOException {
        File newFile = new File(filePath);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        FileOutputStream fos = new FileOutputStream(newFile);
        byte[] buffer = new byte[4096];
        int len;
        while ((len = zis.read(buffer)) > 0) {
            fos.write(buffer, 0, len);
        }
