public class ClassX {
    public static class PathTraversingZipException extends Exception {
        public PathTraversingZipException(String message) {
            super(message);
        }
    }

    public static void unzip(String zipFilePath, String destDirectory) throws PathTraversingZipException {
        if (!destDirectory.endsWith(File.separator)) {
            destDirectory += File.separator;
        }

        File destDir = new File(destDirectory);

        try (ZipInputStream is = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = is.getNextEntry();

            while (entry != null) {
                String dirName = destDirectory + entry.getName();
                File destFile = new File(dirName);

                // Kiểm tra xem đường dẫn của thành viên là '../' hay không
                if (dirName.contains("../")) {
                    throw new PathTraversingZipException("Path traversal detected in zip entry: " + entry.getName());
                }

                // Kiểm tra các thành viên không phải là thư mục
                if (!entry.isDirectory()) {
                    extractFile(is, destFile);
                }
                is.closeEntry();
                entry = is.getNextEntry();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void extractFile(ZipInputStream zipIn, File file) {
        FileOutputStream fos = null;
        try {
            fos = new FileOutputStream(file);
            byte[] bytesIn = new byte[4096];
            int n;
            while ((n = zipIn.read(bytesIn)) != -1) {
                fos.write(bytesIn, 0, n);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                fos.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        try {
            unzip("path_to_your_zip_file.zip", "destination_directory");
        } catch (PathTraversingZipException e) {
            System.err.println(e.getMessage());
