import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class ClassX {
    /**
     * Entpackt ein Zip-Archiv an das angegebene Ziel, nachdem die Mitgliedspfade überprüft wurden.
     * 
     * Die Funktion durchläuft die Mitglieder des Archivs und versucht, Pfadtraversierung zu verhindern, indem sie überprüft, ob der Mitgliedsname '..' enthält.
     */
    public void extractZipArchive(String zipFilePath, String destDirPath) {
        // Erstellen des Zielordners, wenn er nicht existiert
        File destDir = new File(destDirPath);
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        // Öffnen eines InputStream aus dem Zip-Archiv
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFilePath))) {
            ZipEntry entry = zis.getNextEntry();
            while (entry != null) {
                String filePath = destDirPath + File.separator + entry.getName();

                // Wenn das Ergebnis der Überprüfung der Pfadtraversierung 'false' ist, wird das Mitglied nicht extrahiert.
                if (isDirectoryTraversalAllowed(entry.getName())) {
                    // Ein Verzeichnis wurde gefunden
                    File destDirFile = new File(filePath);
                    destDirFile.mkdirs();
                } else {
                    // Ein Datei wurde gefunden
                    extractFile(zis, filePath);
                }

                // Den nächsten Eintrag abrufen
                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Prüft, ob der Pfadname die Pfadtraversierung vorsieht.
     * 
     * @param path Der Pfadname, der geprüft werden soll.
     * @return true, wenn die Pfadtraversierung vorsieht, false sonst.
     */
    private boolean isDirectoryTraversalAllowed(String path) {
        // Auf '..' prüfen, ob dieser Teil des Pfadnames enthalten ist
        return !path.contains("..");
    }

    /**
     * Extrahiert eine Datei aus dem Zip-InputStream zum angegebenen Zielpfad.
     * 
     * @param zis Der zu verwendende InputStream.
     * @param filePath Der Zielpfad.
     * @throws Exception Fehler beim Extrahieren der Datei.
     */
    private void extractFile(ZipInputStream zis, String filePath) throws Exception {
        File destFile = new File(filePath);
        try (FileOutputStream fos = new FileOutputStream(destFile)) {
            byte[] buffer = new byte[1024];
            int length;
            while ((length = zis.read(buffer)) > 0) {
                fos.write(buffer, 0, length);
            }
        }
    }
