import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {
    public static void extractZip(File zipFile, File destDir) {
        if (destDir == null || !destDir.isDirectory()) {
            throw new IllegalArgumentException("Destination directory is invalid or does not exist.");
        }

        try (FileInputStream fis = new FileInputStream(zipFile);
             ZipInputStream zis = new ZipInputStream(fis)) {

            ZipEntry entry = zis.getNextEntry();
            while (entry != null) {
                String fileName = entry.getName();

                // Check for ".." in the file name to prevent path traversal
                Pattern pattern = Pattern.compile("\\\\.\\.");
                Matcher matcher = pattern.matcher(fileName);

                if (matcher.find()) {
                    continue; // Skip this file if it contains ".."
                }

                File destFile = new File(destDir, fileName);

                File parent = destFile.getParentFile();
                if (!parent.exists()) {
                    parent.mkdirs(); // Create necessary directories
                }

                if (entry.isDirectory()) {
                    // If it's a directory, create the directory if it doesn't exist
                    destFile.mkdirs();
                } else {
                    // If it's a file, write its contents
                    try (FileOutputStream fos = new FileOutputStream(destFile)) {
                        byte[] buffer = new byte[1024];
                        int length;
                        while ((length = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, length);
                        }
                    }
                }

                zis.closeEntry();
                entry = zis.getNextEntry();
            }
        } catch (Exception e) {
            throw new RuntimeException("Error extracting archive: " + e.getMessage(), e);
        }
    }
}
