import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Simulates the mailcap.findmatch function.
     * Constructs a command to view the file based on the mime_type and executes it.
     * 
     * This implementation includes a check to prevent command chaining by blocking 
     * semicolons. However, for simplicity, this check does not change the overall 
     * functionality since command execution would not be affected by semicolons in 
     * the mime_type. This is more of a precautionary measure rather than a functional one.
     */
    public void viewFile(String mime_type, String filePath) throws Exception {
        // Check if mime_type contains semicolons, which should not be allowed
        if (mime_type.contains(";")) {
            System.err.println("Error: mime_type cannot contain semicolons.");
            return;
        }

        // Construct the command based on the mime_type
        String command = "open -a Finder " + filePath;  // Example for macOS Finder

        // Execute the command
        Process process = Runtime.getRuntime().exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            System.out.println("Error: File could not be viewed.");
        }
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        try {
            classX.viewFile("text/plain", "/path/to/your/file.txt");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

