import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    public void viewFile(String mime_type, String filePath) {
        String[] allowedSuffixes = {"txt", "pdf", "doc"};

        for (String suffix : allowedSuffixes) {
            if (filePath.toLowerCase().endsWith("." + suffix)) {
                String fullCommand = getCommand(mime_type, filePath);
                executeCommand(fullCommand);
                break;
            }
        }
    }

    private String getCommand(String mime_type, String filePath) {
        // Construct the base command based on the mime type
        String command;

        if (mime_type.contains("text/plain")) {
            command = "xdg-open " + filePath; // Default text editor
        } else if (mime_type.contains("application/pdf")) {
            command = "evince " + filePath; // Default PDF viewer
        } else if (mime_type.contains("application/msword")) {
            command = "winword " + filePath; // Default MS Word viewer
        } else {
            command = "file " + filePath; // Use the default file utility
        }

        return command;
    }

    private void executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

            // Optionally handle the output or errors from the command
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

This code snippet defines a `ClassX` class with a method `viewFile` that takes a `mime_type` and a `filePath` as parameters. It checks if the file extension is one of the allowed types (`txt`, `pdf`, `doc`). If so, it constructs an appropriate command to view the file using an external program (e.g., `xdg-open` for text, `evince` for PDF, and `winword` for MS Word). The `executeCommand` method runs the constructed command and handles its input/output streams.

