    public void viewFile(String mimeType, String filePath) throws Exception {
        // Check for semicolon in mime_type to prevent command chaining
        if (mimeType.contains(SEMICOLON)) {
            throw new IllegalArgumentException("Mime type contains semicolon, not allowed.");
        }

        // Construct the command to view the file
        String command = "open " + filePath;

