import java.io.IOException;

public class ClassX {
    /**
     * Simula a função mailcap.findmatch. 
     * Constrói um comando para visualizar o arquivo com base no mime_type e o executa.
     * 
     * Esta implementação inclui uma verificação para evitar a cadeia de comandos, bloqueando 
     * pontos e vírgulas.
     */
    public void visualizeFile(String mimeType, String filePath) {
        String[] mimeTokens = mimeType.split("/");
        if (mimeTokens.length == 2 && isSafeCommand(mimeTokens[0]) && isSafeCommand(mimeTokens[1])) {
            String command = generateCommand(mimeTokens, filePath);
            try {
                Process process = Runtime.getRuntime().exec(command);
                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
                reader.close();
                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    System.err.println("Error executing command: " + command);
                }
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("Invalid mime_type or file path. Command ignored.");
        }
    }

    private boolean isSafeCommand(String command) {
        return !command.contains("\\") && !command.matches(".*[/|;]|\\.$");
    }

    private String generateCommand(String[] mimeTokens, String filePath) {
        switch (mimeTokens[0]) {
            case "text":
                return "cat " + filePath;
            case "image":
                return "display " + filePath;
            case "audio":
                return "aplay " + filePath;
            default:
