                    String key = line.substring(0, index).trim();
                    String value = line.substring(index + 1).trim();
                    if (!mimetypes.containsKey(key)) {
                        mimetypes.put(key, new ArrayList<>());
                    }
                    mimetypes.get(key).add(value);
                }
            }
            reader.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
