        try {
            System.out.println("Enter MIME type:");
            String mimeType = reader.readLine();

            // Split the MIME type into components
            String[] parts = mimeType.split("\\s+");

            // Check if the input contains any special characters or spaces that may cause an error in the command
            boolean hasSpecialChars = Arrays.asList(parts).stream().anyMatch(part -> !part.matches("[a-zA-Z0-9]+"));

            if (hasSpecialChars) {
                System.out.println("Invalid MIME type: cannot contain special characters.");
            } else {
                // Construct the command to open the file with the correct application
                StringBuilder command = new StringBuilder("xdg-open");
                for (String part : parts) {
                    command.append(" ").append(part);
                }

                // Execute the command using Runtime.exec
                Process process = Runtime.getRuntime().exec(command.toString());

                // Read the output of the command
                BufferedReader processReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String outputLine;
                while ((outputLine = processReader.readLine()) != null) {
                    System.out.println(outputLine);
                }

                // Close input streams and wait for the process to complete
                processReader.close();
                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    System.out.println("Failed to open file.");
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                reader.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
