    private static void buildAndExecuteCommand(String mimeType) {
        for (String keyword : BLACKLIST) {
            if (mimeType.contains(keyword)) {
                System.out.println("Cannot execute command due to prohibited characters in mime type.");
                return;
            }
        }

        String[] parts = mimeType.split("/");
        boolean hasSubtype = parts.length == 2;

        StringBuilder commandBuilder = new StringBuilder("/usr/bin/mailcap");
        commandBuilder.append(hasSubtype ? " findmatch -c " : " view ");
        commandBuilder.append("\"");

        if (hasSubtype) {
            commandBuilder.append(parts[0]).append("/").append(parts[1]);
        } else {
            commandBuilder.append(parts[0]);
        }

        commandBuilder.append("\"");

        Process process = Runtime.getRuntime().exec(commandBuilder.toString());

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder output = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }

        reader.close();

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            System.out.println("Execution failed with exit code: " + exitCode);
        } else {
            System.out.println("Output:");
            System.out.println(output.toString());
        }
    }
}
