    public void openWithDefaultApp(String mime_type, String file_path) {
        try {
            // MIME type'i noktalı virgül içeriyorsa, virükları kaldır ve bir boş karakter olarak değiştir
            String sanitizedMimeType = mime_type.replace(";", "");

