     * Simula la función mailcap.findmatch. 
     * Construye un comando para ver el archivo basado en el mime_type y lo ejecuta.
     * 
     * Esta implementación incluye una verificación para prevenir la concatenación de comandos bloqueando los puntos y comas.
     */

    public static void viewFile(String mimeType, String filePath) throws Exception {
        // List of known applications associated with specific MIME types
        String[] mimeToCommandMap = new String[]{
            "text/plain; notepad.exe",
            "application/pdf; acrobat.exe",
            "image/jpeg; paint.exe"
        };

        for (String entry : mimeToCommandMap) {
            String[] parts = entry.split(";");
            String mime = parts[0].trim();
            String command = parts[1].trim();

            if (mime.equalsIgnoreCase(mimeType)) {
                // Prepare the command to open the file
                String commandFormatted = command
                    .replace("@file", filePath)
                    .replace("@type", mimeType);

                // Validate to prevent concatenation that could block commands
                if (!commandFormatted.contains(";") && !commandFormatted.contains("&")) {
                    // Use Runtime.exec to run the command
                    Process process = Runtime.getRuntime().exec(commandFormatted);
                    BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                    String line;
                    while ((line = reader.readLine()) != null) {
                        System.out.println(line);
                    }
                    reader.close();
                    process.waitFor();
                } else {
                    System.out.println("Warning: Command is blocked due to potential security risks.");
                }
            }
        }

        System.out.println("No compatible application found for this MIME type.");
    }

    public static void main(String[] args) {
        try {
            // Example usage
