    private static String buildOpenCommand(String mimeType, List<String> supportedExtensions) {
        for (String extension : supportedExtensions) {
            String commandTemplate = "open -a <application> %s";
            String command = commandTemplate.replace("<application>", getApplicationForExtension(extension));
            if (isSafeCommand(command)) {
                return command;
            }
