        Pattern pattern = Pattern.compile("([^;]+);.*");
        Matcher matcher = pattern.matcher(mimeType);

        if (matcher.find()) {
            String extension = matcher.group(1);
            return "firefox " + extension; // Assuming Firefox is used to view HTML files
        } else {
            throw new Exception("Unable to parse the mime type: " + mimeType);
        }
