public class ClassX {
    public static void simulaMailcap(String mime_type, String filePath) {
        // Split the mime type to avoid command injection
        StringTokenizer st = new StringTokenizer(mime_type);
        if (st.countTokens() == 0) {
            System.out.println("MIME type is empty or invalid.");
            return;
        }

        // Extract the main MIME type
        String mainMime = st.nextToken();

        // Check for command injection by not allowing ';' in the main MIME type
        if (mainMime.contains(";")) {
            System.out.println("Command injection detected. Aborting.");
            return;
        }

        // Build the command
        StringBuilder command = new StringBuilder()
                .append("open ")
                .append(filePath)
                .append(" -a ");
        while (st.hasMoreElements()) {
            command.append(st.nextToken()).append(' ');
        }
        command.trim();

        // Execute the command
        try {
            Process process = Runtime.getRuntime().exec(command.toString());
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        String mimeType = "text/html; charset=UTF-8";
        String filePath = "path/to/your/file.html";
        simulaMailcap(mimeType, filePath);
    }
}
