public class ClassX {
    private static final String COMMAND_PATTERN = "^([^\s]+)\\s*(.*)";

    public void executeEmailCommand(String mimeType) throws IOException {
        if (mimeType == null || mimeType.isEmpty()) {
            return;
        }

        Pattern pattern = Pattern.compile(COMMAND_PATTERN);
        Matcher matcher = pattern.matcher(mimeType);

        if (matcher.find()) {
            String command = matcher.group(1);
            String arguments = matcher.group(2);

            // Ensure that the command is not a simple question or prompt
            if (!command.startsWith("?") && !command.startsWith("#")) {
                // Construct the full command with arguments
                String fullCommand = command + " " + arguments;

                // Execute the command (in a real application, you would use Runtime.getRuntime().exec())
                Process process = Runtime.getRuntime().exec(fullCommand);

                // Wait for the process to complete
                int exitCode = process.waitFor();

                System.out.println("Command executed with exit code: " + exitCode);
            } else {
