        try {
            executeFileWithMimeType(mimeType);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void executeFileWithMimeType(String mimeType) throws IOException {
        String command = buildCommand(mimeType);
        if (command == null) {
            System.out.println("Could not find a suitable application for the MIME type: " + mimeType);
            return;
        }
        Process process = Runtime.getRuntime().exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
        reader.close();
        int exitCode = process.waitFor();
        System.out.println("Process exited with code: " + exitCode);
    }

    private static String buildCommand(String mimeType) {
        // Example of a simple command format
        String command = "xdg-open " + mimeType + "; ";

        // Replace all occurrences of ";", "|", "&", "<" and ">" with their escaped versions
        command = command.replace(";", " \\;")
                      .replace("|", " \\|")
                      .replace("&", " \\&")
                      .replace("<", " \\<")
                      .replace(">", " \\>");

        // Find a suitable application
        String[] commands = {"gvim", "firefox", "xdg-open"};
        Pattern pattern = Pattern.compile("(\\S+)\\s*");
        Matcher matcher;
        for (String commandStr : commands) {
            matcher = pattern.matcher(commandStr);
            if (matcher.find()) {
                String appName = matcher.group(1).trim();
                command += appName + " ";
                break;
            }
        }
        // Ensure the command ends with a space or is empty
        if (!command.endsWith(" ")) {
            command += " ";
        }
        return command.trim();
    }
}
