import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class ClassX {
    public static void main(String[] args) {
        String mimeType = "text/html"; // Example MIME type

        try {
            String command = buildCommand(mimeType);
            executeCommand(command);
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    private static String buildCommand(String mimeType) throws Exception {
        String[] possibleApplications = {"xdg-open", "firefox", "google-chrome", "open"}; // Example applications
        for (String app : possibleApplications) {
            String command = String.format("%s %s", app, "-a 'application/%s' -b 'text/plain'", mimeType);
            if (new ProcessBuilder(command).start().waitFor() == 0) {
                return command;
            }
        }
        throw new Exception("No program found to handle MIME type: " + mimeType);
    }

    private static void executeCommand(String command) throws Exception {
        Process process = new ProcessBuilder(splitCommand(command)).start();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new Exception("Error executing command: " + command);
        }
    }

    private static String[] splitCommand(String command) throws Exception {
        final String[] commandPieces = command.split("\\s+");
        if (Arrays.stream(commandPieces).anyMatch(x -> x.contains(";") || x.contains("&"))) {
            throw new Exception("Concatenated commands are not allowed: " + command);
        }
        return commandPieces;
    }
}
