import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    public String findMatch(String mimeType) {
        // Simula la funzione mailcap.findmatch con pattern regolari
        if (mimeType == null || mimeType.isEmpty()) {
            return "Mime type is empty or null";
        }

        // Regexp per trovare l'estensione corrispondente al mime-type
        String regexPattern = "(?<extension>\\.[^;]*)";
        Pattern pattern = Pattern.compile(regexPattern);
        Matcher matcher = pattern.matcher(mimeType);

        if (!matcher.matches()) {
            return "No valid extension found for mime type: " + mimeType;
        }

        String extension = matcher.group("extension");

        // Prendi l'esecutore del sistema dalla shell
        String exe = System.getenv("SHELL");
        if (exe == null) {
            exe = "/bin/sh";
        }

        // Costruisce un comando per visualizzare il file
        String command = exe + " -c 'more " + extension + "'";

        // Esegui il comando
        ProcessBuilder pb = new ProcessBuilder(command);
        try {
            Process process = pb.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            int exitCode = process.waitFor();
            if (exitCode != 0) {
                System.err.println("Error executing command: " + exitCode);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        return "File displayed successfully";
    }
}
```
