public class ClassX {

    public static void findMatch(String mimeType) throws Exception {
        // Definiere den Pfad zur Datei mailcap
        String mailcapPath = "mailcap";

        // Erstelle einen BufferedReader zum Lesen der Inhalte der mailcap-Datei
        BufferedReader reader = new BufferedReader(new InputStreamReader(ClassX.class.getResourceAsStream(mailcapPath)));

        // Lese Zeile für Zeile und such nach einem Eintrag mit dem angegebenem mime_type
        String line;
        while ((line = reader.readLine()) != null) {
            // Überprüfe das Format des Eintrags
            if (line.matches("([^=]+)=\\\"([^;]+);.*")) {
                String type = Matcher.group(1);
                String command = Matcher.group(2).replace(';', '\n');

                // Überprüfe, ob der mime_type passt
                if (type.equals(mimeType)) {
                    // Führe den Befehl aus
                    ProcessBuilder pb = new ProcessBuilder(command.split("\n"));
                    pb.inheritIO();
                    pb.start().waitFor();
                    return;
                }
            }
        }

        // Fallback oder Fehlermeldung, falls kein passender Eintrag gefunden wurde
        System.out.println("Kein passender Eintrag für MIME-Type: " + mimeType);
    }

    public static void main(String[] args) {
        try {
            // Beispielaufruf der Methode findMatch
            findMatch("text/plain");
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
