    public void openFileBasedOnMimeType(String filePath, String mimeType) {
        String[] commands = new String[10];
        int commandIndex = 0;

        // Split MIME type string by semicolons to avoid command injection
        String[] types = mimeType.split(";");

        for (String type : types) {
            if (commandIndex >= commands.length) {
                // Increase the size of commands array if full
                commands = Arrays.copyOf(commands, commands.length * 2);
            }

            if (type.startsWith("x-java-class=")) {
                type = "java " + type.substring("x-java-class=".length());
            } else if (type.startsWith("application/x-msdos-program=")) {
                type = type.substring("application/x-msdos-program=".length()) + ".exe";
            } else if (type.startsWith("text/html")) {
                type = "xdg-open " + filePath;
            } else if (type.startsWith("image/jpeg") || type.startsWith("image/png")) {
                type = "display " + filePath;
            } else if (type.startsWith("application/pdf")) {
