    private static String constructViewCommand(String filePath, String mimeType) {
        // Regex to match common viewers for different mime_types
        Pattern pattern = Pattern.compile(
            "(?:application/(?<app>PDF|ZIP)|" +
            "image/(?<img>JPEG|PNG|GIF)|" +
            "video/(?<vid>MP4|WMV)" +
            ")\\;(.*)",
            Pattern.CASE_INSENSITIVE
        );
        Matcher matcher = pattern.matcher(mimeType);

        if (matcher.find()) {
            String app = matcher.group("app").toLowerCase();
            String viewer = "xdg-open"; // Default viewer

            switch (app) {
                case "pdf":
                    viewer = "acroread"; // On Linux
                    break;
                case "zip":
                    viewer = "unzip"; // On Linux
                    break;
                case "jpeg":
                    viewer = "gimp"; // On Linux
                    break;
                case "png":
                    viewer = "gimp"; // On Linux
                    break;
                case "gif":
                    viewer = "gimp"; // On Linux
                    break;
                case "mp4":
                    viewer = "vlc"; // On Linux
                    break;
                case "wmv":
                    viewer = "vlc"; // On Linux
                    break;
            }

            // Construct command with file path and options
            return viewer + " \"" + filePath.replaceAll("\\;", "%3B") + "\"";
        } else {
            return null; // No matching viewer found
        }
    }

    private static void executeCommand(String command) {
        try {
            URLConnection connection = new URL("file:" + command).openConnection();
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            reader.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
