import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;

public class SecurityFilterInputStream extends FilterInputStream {
    public SecurityFilterInputStream(InputStream in) {
        super(in);
    }

    @Override
    public int read() throws IOException {
        int b = readByte();
        return (b != '<') ? b : -1;
    }

    @Override
    public int read(byte[] b, int off, int len) throws IOException {
        byte[] newBuffer = new byte[len];
        for (int i = 0; i < len; i++) {
            int b = readByte();
            if (b == -1) {
                break;
            } else if (b != '<') {
                newBuffer[i] = (byte) b;
            }
        }
        return len - newBuffer.length;
    }

    private int readByte() throws IOException {
        int b = super.read();
        if (b == '<') {
            // Read until we find the end of the tag or reach the end of the stream
            while (read() != '>') {
                // Skip non-tag characters
                if (read() == '<') {
                    throw new IOException("Blocked <script> content");
                }
            }
        }
        return b;
    }
}

