import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Tervehdi käyttäjää käyttäen mallia (mockattu).
     * 
     * Toiminto yrittää puhdistaa syötteen estämällä nimenomaan <script>-tageja.
