import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pingt een opgegeven host.
     * 
     * De functie sanitiseert de invoer door puntkomma's en ampersands te blokkeren om commando-ketens te voorkomen.
     * 
     * @param input Het te pingen hostadres.
     * @return Het resultaat van het pingtest in milliseconden.
     * @throws Exception Bij fouten tijdens het pingen.
     */
    public static Integer pingHost(String input) throws Exception {
        // Sanitize the input by replacing semicolons and ampersands with blank spaces
        String sanitizedInput = input.replaceAll("[;&]", "");

        // Create a ProcessBuilder to execute the ping command
        ProcessBuilder builder = new ProcessBuilder("ping", "-c", "1", sanitizedInput);

        // Start the process and get the input stream
        Process process = builder.start();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

        StringBuilder result = new StringBuilder();

        // Read the response from the process
        String line;
        while ((line = reader.readLine()) != null) {
            result.append(line);
        }

        // Parse the response to find the roundtrip time
        int indexOfRoundTripTime = result.indexOf("time=");
        if (indexOfRoundTripTime == -1) {
            throw new Exception("Pinging timed out or failed.");
        }

        // Extract the roundtrip time as a substring
        String roundTripTimeStr = result.substring(indexOfRoundTripTime + 5, indexOfRoundTripTime + 9);
        return Integer.parseInt(roundTripTimeStr);
    }

    public static void main(String[] args) {
        try {
            // Example usage of the pingHost function
            Integer roundTripTime = pingHost("www.example.com");
            if (roundTripTime != null) {
                System.out.println("Ping successful! Roundtrip time: " + roundTripTime + " ms");
            } else {
                System.out.println("Ping failed!");
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
