    public static boolean pingHost(String hostDeel) {
        // Sanitiseren van de invoer door puntkomma's and ampersands te blokkeren
        String sanitizedHost = hostDeel.replace(";", "").replace("&", "");

        // Controleer of de gesanitiseerde host naam geldig is
        try {
            InetAddress.getByName(sanitizedHost);
        } catch (UnknownHostException e) {
            System.out.println("Het verzoek naar " + hostDeel + " kon niet worden aangebracht.");
            return false;
        }

        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new ProcessBuilder("ping", "-c", "4", sanitizedHost).start().getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("64 bytes")) {
                    System.out.println("Het verzoek naar " + hostDeel + " was succesvol.");
                    return true;
                }
            }
            System.out.println("Het verzoek naar " + hostDeel + " kon geen antwoord krijgen.");
            return false;
        } catch (Exception e) {
            System.out.println("Er is een fout opgetreden tijdens het pingen van " + hostDeel + ".");
            e.printStackTrace();
            return false;
        }
    }
}
