        boolean responseRecieved = false;
        while ((line = reader.readLine()) != null) {
            if (line.contains("Reply from")) {
                responseRecieved = true;
                break;
            }
        }

        // Beenden des Prozesses
        process.destroy();

        return responseRecieved;
    }

