     */
    public void pingHost(String host) {
        if (host == null || host.isEmpty()) {
            throw new IllegalArgumentException("Die Host-Eingabe darf nicht leer sein.");
        }

        // Erstellen eines BufferedReader zur Standard-Eingabe
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String input = null;

        try {
            while ((input = reader.readLine()) != null) {
                // Check for semicolons or ampersands
                if (input.contains(";") || input.contains("&")) {
                    System.out.println("Fehler: Nicht erlaubte Zeichen wie ';', '&' verhindern eine Befehlsverkettung.");
                } else {
                    // Perform the ping command
                    ProcessBuilder pb = new ProcessBuilder("ping", "-c", "4", host);
                    Process p = pb.start();
                    BufferedReader stdInput = new BufferedReader(new InputStreamReader(p.getInputStream()));
                    BufferedReader stdError = new BufferedReader(new InputStreamReader(p.getErrorStream()));

                    System.out.print("Ping-Resultat für " + host + ": ");
                    String line;
                    while ((line = stdInput.readLine()) != null) {
                        System.out.println(line);
                    }

                    while ((line = stdError.readLine()) != null) {
                        System.err.println(line);
                    }

                    p.waitFor();
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                reader.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        classX.pingHost("example.com");
    }
}
