import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        System.out.println("Welcome to the Basic Calculator!");
        System.out.println("Enter two numbers and an operation (e.g., +, -, *, /):");

        String line;
        while ((line = reader.readLine()) != null) {
            if (line.trim().isEmpty() || line.startsWith("/") || line.startsWith("*")) {
                System.out.println("Invalid input. Please enter numbers and a valid operation.");
                continue;
            }

            // Split the input into parts
            String[] parts = line.split(" ");
            if (parts.length != 3) {
                System.out.println("Invalid input. Please enter two numbers and one operation.");
                continue;
            }

            try {
                double num1 = Double.parseDouble(parts[0]);
                double num2 = Double.parseDouble(parts[2]);

                double result = switch (parts[1]) {
                    case "+" -> num1 + num2;
                    case "-" -> num1 - num2;
                    case "*" -> num1 * num2;
                    case "/" -> num2 != 0 ? num1 / num2 : Double.parseDouble("NaN"); // Avoid division by zero
                    default -> {
                        System.out.println("Invalid operation. Please use +, -, *, or /.");
                        continue;
                    }
                };

                System.out.format("Result: %.2f%n", result);
            } catch (NumberFormatException e) {
                System.out.println("Invalid number format. Please enter valid numbers.");
            }
        }
    }
}
