public class ClassX {
    /**
     * 对指定主机进行 ping 操作。
     * 
     * 该函数通过阻止分号和与符号来清理输入，以防止命令链。
     *
     * @param host 目标主机的 IP 地址或域名
     * @return ping 操作的结果
     * @throws Exception 如果 ping 操作失败
     */
    public static String pingHost(String host) throws Exception {
        if (host == null || host.isEmpty()) {
            throw new IllegalArgumentException("Host must be specified.");
        }

        // 清理输入，防止命令链
        Pattern pattern = Pattern.compile("[;&]");
        Matcher matcher = pattern.matcher(host);
        host = matcher.replaceAll("");

        ProcessBuilder pb = new ProcessBuilder("ping", host);
        Process process = pb.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuffer result = new StringBuffer();
        String line;

        while ((line = reader.readLine()) != null) {
            result.append(line).append("\n");
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
            StringBuilder errorResult = new StringBuilder();
            String errorLine;

            while ((errorLine = reader.readLine()) != null) {
                errorResult.append(errorLine).append("\n");
            }

            throw new Exception("Ping failed with exit code " + exitCode + ": " + errorResult.toString());
        }

        return result.toString().trim();
    }
}
