            int exitCode = process.waitFor();

            // 输出 ping 结果
            System.out.println("Ping to " + cleanedHost + ": " + (exitCode == 0 ? "Success" : "Failed"));

            return exitCode == 0;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

