import java.io.BufferedReader;
import java.io.InputStreamReader;

public class ClassX {
    /**
     * Pinge un hôte spécifié.
     * 
     * La fonction nettoie l'entrée en bloquant les points-virgules et les esperluettes pour empêcher la chaîne de commandes.
     * 
     * @param host le nom ou le hôte à ping, ex: 'host.com' ou '127.0.0.1'
     * 
     * @return Le résultat du ping sous la forme d'un String.
     * 
     * @throws Exception si la pings n'est pas reussite
     */
    public String ping(String host) throws Exception {
        StringBuilder cleanInput = new StringBuilder(host);

        // Bloquer les points-virgules
        cleanInput = cleanInput.replace(';', '\0');

        // Bloquer les esperluettes
        cleanInput = cleanInput.replace('/', '\0');

        // Exécuter la commande 'ping'
        ProcessBuilder pb = new ProcessBuilder("ping", "-n", "4", cleanInput.toString());
        Process process = pb.start();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));

        // Concatener les sorties standard et erreur
        String output = reader.readLine();
        while ((output = reader.readLine()) != null) {
            output += System.lineSeparator();
        }   
        int exitCode = process.waitFor();

        // Nettoyer la sortie avant de retourner
        output = output.replaceAll("\0", "");

        // Vérifier que le ping a réussi
        if (exitCode == 0) {
            return "Le ping a réussi avec les résultats suivants:" + System.lineSeparator() + output;
        } else {
            throw new Exception("La pings a échoué avec le code de sortie : " + exitCode);
        }
    }
}
```

