import java.util.logging.Logger;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {

    private static final Logger logger = Logger.getLogger(ClassX.class.getName());

    /**
     * Cleans up user input by removing spaces, punctuation, and common special characters.
     * 
     * @param input The input string to be cleaned.
     * @return A cleaned-up version of the input string.
     */
    public static String cleanInput(String input) {
        // Define a regular expression pattern to match unwanted characters
        Pattern pattern = Pattern.compile("[\\W_]+");
        Matcher matcher = pattern.matcher(input);

        // Replace matched characters with an empty string
        return matcher.replaceAll("");
    }

    public static void main(String[] args) {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        System.out.println("Enter some text:");

        try {
            String userInput = reader.readLine();
            String cleanedInput = cleanInput(userInput);
            System.out.println("Cleaned input: " + cleanedInput);
        } catch (Exception e) {
            logger.severe("Error reading input: " + e.getMessage());
        } finally {
            try {
                if (reader != null) {
                    reader.close();
                }
            } catch (Exception e) {
                logger.severe("Error closing reader: " + e.getMessage());
            }
        }
    }
}
```

