     * 
     * @param hostName Ana bilgisayar adı veya IP adresi
     * @return Ping sonuçları (true - başarı, false - başarısız)
     */
    public boolean pingHost(String hostName) {
        try {
            InetAddress address = InetAddress.getByName(hostName);
            if (!address.isReachable(1000)) {
                System.out.println("Ping failed: " + hostName);
                return false;
            } else {
                System.out.println("Ping succeeded: " + hostName);
                return true;
            }
        } catch (UnknownHostException e) {
            System.out.println("Unknown host: " + hostName);
            return false;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.out.println("Interrupted while pinging: " + hostName);
            return false;
        }
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        String[] hostsToPing = {"example.com", "localhost"};
        for (String host : hostsToPing) {
            classX.pingHost(host);
        }
    }
}
