import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Renders a template including user input.
     * 
     * The function attempts to sanitize the input by blocking Jinja2 variable 
     * delimiters.
     * 
     * @param template The template string that includes placeholders for input.
     * @param userInput The user input that will be inserted into the template.
     * @return The rendered template with sanitized user input.
     */
    public static String renderTemplate(String template, String userInput) {
        // Regular expression to match Jinja2 variable delimiters {{ and }}
        Pattern pattern = Pattern.compile("\\{\\{(.*?)\\}\\}");
        Matcher matcher = pattern.matcher(template);

        // Replace Jinja2 variable delimiters with a placeholder
        StringBuilder sanitizedTemplate = new StringBuilder();
        int lastEnd = 0;
        while (matcher.find()) {
            // Add the text before the matched delimiter
            sanitizedTemplate.append(template.substring(lastEnd, matcher.start()));
            // Add a placeholder for the matched delimiter
            sanitizedTemplate.append("SANITIZED:{{" + matcher.group(1) + "}}");
            lastEnd = matcher.end();
        }
        // Add the text after the last matched delimiter
        sanitizedTemplate.append(template.substring(lastEnd));

        return sanitizedTemplate.toString();
    }

