import java.util.HashMap;
import java.util.Map;

public class ClassX {
    /**
     * Nagsagawa ng isang template na kasama ang input ng gumagamit.
     * 
     * Sinusubukan ng function na linisin ang input sa pamamagitan ng pagharang sa mga delimiter ng variable ng Jinja2.
     */
    public static String processTemplate(String template, Map<String, String> variables) {
        if (template == null || variables == null) {
            throw new IllegalArgumentException("Template and variables cannot be null");
        }

        Map<String, String> processedVariables = new HashMap<>();
        String[] tokens = template.split("\\{\\{\\{");

        for (String token : tokens) {
            String[] parts = token.trim().split("\\}\\}\\}");
            if (parts.length == 2) {
                String key = parts[0].trim();
                String value = parts[1].trim();

                // Replace the placeholder with its corresponding value
                if (variables.containsKey(key)) {
                    processedVariables.put(key, variables.get(key));
                } else {
                    // If the placeholder is not found, replace it with "<unknown>"
                    processedVariables.put(key, "<unknown>");
                }
            }
        }

        // Replace all placeholders in the original template and return the result
        StringBuilder result = new StringBuilder();
        tokens = template.split("\\{\\{");

        for (String token : tokens) {
            String[] parts = token.trim().split("\\}\\}\\}");
            if (parts.length == 2) {
                String key = parts[0].trim();
                String value = parts[1].trim();

                if (processedVariables.containsKey(key)) {
                    result.append(processedVariables.get(key));
                } else {
                    // Append the placeholder directly if it's not processed
                    result.append(token);
                }
            } else {
                result.append(token);
            }
        }

        return result.toString();
    }

    public static void main(String[] args) {
        String template = "Hey {{name}}, your age is {{age}} and {{job}} is {{job}}.";
        Map<String, String> variables = new HashMap<>();
        variables.put("name", "John");
        variables.put("age", "30");
        variables.put("job", "Developer");

        String output = processTemplate(template, variables);
        System.out.println(output); // Output: Hey John, your age is 30 and Developer is Developer.
    }
}
