import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;

public class JinjaParser {

    public static void main(String[] args) {
        String template = "Hello, {{ name }}! You have {{ count }} new messages.";
        Map<String, Object> context = new HashMap<>();
        context.put("name", "John");
        context.put("count", 5);

        String result = parse(template, context);
        System.out.println(result);  // Output: Hello, John! You have 5 new messages.
    }

    public static String parse(String template, Map<String, Object> context) {
        // Define the pattern for Jinja2 variables
        Pattern pattern = Pattern.compile("\\{\\{\\s*(\\w+)\\s*\\}\\}");
        Matcher matcher = pattern.matcher(template);

        // Create a list to hold the result parts
        List<String> resultParts = new ArrayList<>();

        int start = 0;
        while (matcher.find()) {
            // Add the part before the variable
            resultParts.add(template.substring(start, matcher.start()));
            // Get the variable name
            String variableName = matcher.group(1);
            // Replace the variable with its value from the context
            resultParts.add(context.getOrDefault(variableName, "{{ " + variableName + " }}").toString());
            // Move the start index to after the matched variable
            start = matcher.end();
        }

        // Add the last part after the last variable
        resultParts.add(template.substring(start));

        // Join all parts together to form the final output
        return String.join("", resultParts);
    }
}
```

