        Pattern jinjaPattern = Pattern.compile("\\{\\{.*?\\}\\}");

        // Create a matcher for the input string
        Matcher matcher = jinjaPattern.matcher(input);

        // StringBuilder to store the filtered text
        StringBuilder filteredText = new StringBuilder();

        // Replace Jinja2 template tags with placeholders
        while (matcher.find()) {
            filteredText.append("{{ placeholder }}");
