import java.util.regex.*;

public class TemplateRenderer {
    private Pattern jinjaVariablePattern = Pattern.compile("\\{%\\s*([a-zA-Z_][a-zA-Z0-9_]*)\\s*%\\}", Pattern.CASE_INSENSITIVE);

    public String renderTemplate(String template, Map<String, Object> data) {
        Matcher matcher = jinjaVariablePattern.matcher(template);
        StringBuffer safeTemplate = new StringBuffer();

        while (matcher.find()) {
            matcher.appendReplacement(safeTemplate, "{{ $1 }}");
        }
        matcher.appendTail(safeTemplate);

        return safeTemplate.toString();
    }
}
