import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ClassX {

    /**
     * Rende un modello includendo l'input dell'utente.
     * 
     * La funzione tenta di sanificare l'input bloccando i delimitatori delle variabili Jinja2.
     * 
     * @param input L'input dell'utente da sanitizzare.
     * @return Il modello sanitizzato.
     */
    public String rendeModello(String input) {
        // Definisco i delimitatori Jinja2
        String pattern = "(?<!\\w)\\{\\{(.*?)\\}}(?=\\w)";

        // Creo un pattern per confrontarlo con il testo input
        Pattern regexPattern = Pattern.compile(pattern);

        // Creo un matcher per trovare tutte le corrispondenze
        Matcher matcher = regexPattern.matcher(input);

        // StringBuilder per costruire la stringa sanitizzata
        StringBuilder sanitizedInput = new StringBuilder();

        // Sostituisco le corrispondenze con un carattere o una stringa vuota
        while (matcher.find()) {
            // Aggiungo un carattere come flag di sostituzione
            sanitizedInput.append('#').append(matcher.group(1)).append('#');
        }

        // Aggiungo l'input originale non modificato alle corrispondenze di sostituzione
        sanitizedInput.insert(0, input).reverse().delete(0, input.length());

        return sanitizedInput.toString();
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        String input = "Ciao {{nome}}, sono {{eta}} anni.";
        String sanitizedModello = classX.rendeModello(input);
        System.out.println(sanitizedModello);
    }
}
```

