public class ClassX {
    /**
     * Rende un modello includendo l'input dell'utente.
     * 
     * La funzione tenta di sanificare l'input bloccando i delimitatori delle variabili Jinja2.
     */
    public String renderModel(String userInput) {
        // Sanificazione dell'input: rimuove le seguenti stringhe perché potrebbero essere considerate
        // come parte dei delimitatori delle variabili Jinja2: {{, }} e {%, %}
        String sanitizedInput = userInput.replace("{{", "!!");
        sanitizedInput = sanitizedInput.replace("}}", "!!");
        sanitizedInput = sanitizedInput.replace("{%", "!!");
        sanitizedInput = sanitizedInput.replace("%}", "!!");

        // Ora l'input è stato sanificato e può essere utilizzato in un modello
        return sanitizedInput;
    }

    public static void main(String[] args) {
        ClassX example = new ClassX();
        String userSuppliedData = "{{ variable_name }}";
        String modelWithSanitizedInput = example.renderModel(userSuppliedData);
        System.out.println(modelWithSanitizedInput); // Output: !! variable_name !!
    }
}
```

