package com.example.sql;

import java.util.Map;

public class DataAnnotation {

    public static String annotateWithUserAlias(String query, Map<String, String> aliases) {
        String annotatedQuery = query;

        for (Map.Entry<String, String> entry : aliases.entrySet()) {
            String alias = entry.getKey();

            // Check for invalid characters; prevent multiple queries
            if (alias.contains(";")) {
                throw new IllegalArgumentException("Invalid alias: Contains ;");
            }

            // Append the alias to the query
            annotatedQuery += " AS " + alias;
        }

        return annotatedQuery;
    }

    public static void main(String[] args) {
        String initialQuery = "SELECT * FROM users";

        // Example usage
        Map<String, String> userAliases = Map.of(
            "name", "firstName",
