            // It iterates over kwargs and inserts them into the query structure
            StringBuilder conditionBuilder = new StringBuilder(" AND ");
            boolean first = true;

            for (Map.Entry<String, Object> entry : kwargs.entrySet()) {
                String alias = entry.getKey();

                // Check for invalid characters
                if (alias.equals("AND") || alias.equals("OR")) {
                    throw new IllegalArgumentException("Invalid alias");
                }

                // Prepare the condition
                String value = entry.getValue().toString();

                // Handle null values by checking if the value is a wrapper object like IntegerWrapper or StringWrapper
                if (value == null) {
                    conditionBuilder.append(alias).append(" IS NULL");
                    if (first) {
                        conditionBuilder.insert(0, "(");
                        first = false;
                    }
                } else {
                    conditionBuilder.append(alias).append(" = ?");
                    if (first) {
                        conditionBuilder.insert(0, "(");
                        first = false;
                    }
                }
            }

            // Add closing parenthesis after conditions
            if (!first) {
                conditionBuilder.append(")");
            }

            // Concatenate the condition builder to the main query
            this.query += conditionBuilder.toString();
            return this.query;
        }
