public class ClassX {

    // Mock Query Class
    public static class MockQuerySet {
        private String query = "SELECT * FROM table";

        public String annotate(Map<String, String> kwargs) {
            // Annotates the query with the provided key-value pairs
            StringBuilder annotatedQuery = new StringBuilder(this.query);

            for (Map.Entry<String, String> entry : kwargs.entrySet()) {
                String alias = entry.getKey();

                // Validate alias
                if (alias.contains(";")) {
                    throw new IllegalArgumentException("Invalid alias");
                }

                // Append alias to the query
                annotatedQuery.append(" AS ").append(alias);
            }

            return annotatedQuery.toString();
        }
    }

    /**
     * Nag-aannotate ng data gamit ang alias na ibinigay ng gumagamit.
     * 
     * Ang function ay nag-validate ng alias sa pamamagitan ng pag-block ng mga semicolon upang maiwasan ang maraming query.
     * Ang function ay hindi tumatapos ng kopyan ng mga keyword na SQL upang makukuha ng full na query.
     */
}
