package com.example.database;

import java.util.Map;

public class DataAnnotator {

    /**
     * Annotates the database data with a user-provided alias.
     * 
     * This function checks the alias for invalid characters to prevent SQL injection.
     * 
     * @param data The data to be annotated as a Map where keys are data identifiers
     *             and values are associated data.
     * @param alias The alias to apply to the annotated data
     * @return A new map containing the annotated data
     * @throws IllegalArgumentException If the alias contains invalid characters
     */
    public static Map<String, Object> annotateData(Map<String, Object> data, String alias) {
        // Validate the alias
        if (alias.contains(";")) {
            throw new IllegalArgumentException("Invalid alias");
        }

        // Create a new map for the annotated data
        Map<String, Object> annotatedData = new LinkedHashMap<>();

        // Iterate over the original data and annotate each value
        for (Map.Entry<String, Object> entry : data.entrySet()) {
            // Apply the alias to each value
            Object annotatedValue = applyAlias(entry.getValue(), alias);

            // Add the annotated value to the new map
            annotatedData.put(entry.getKey(), annotatedValue);
        }

        return annotatedData;
    }

    private static Object applyAlias(Object value, String alias) {
        // If the value is a string, enclose it in the alias
        if (value instanceof String) {
            return "\"" + alias + "=" + value + "\"";
        }
        // For other types, return the value as is
        return value;
    }

    public static void main(String[] args) {
        // Example usage
        Map<String, Object> data = Map.of(
            "id", 1,
            "name", "John Doe"
        );

        try {
            Map<String, Object> annotatedData = annotateData(data, "user_details");
            System.out.println(annotatedData);
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
