class PatternBuilder {
    private StringBuilder patternBuilder;
    private String currentCharacter;

    public PatternBuilder() {
        patternBuilder = new StringBuilder("|");
    }

    public PatternBuilder anyOf(char[] characters) {
        for (char c : characters) {
            patternBuilder.append(Character.toLowerCase(c)).append("|");
        }
        return this;
    }

    public String build() {
        if (patternBuilder.length() == 1) {
            return "";
        } else {
            return patternBuilder.substring(0, patternBuilder.length() - 1);
        }
    }
}
