public class ClassX {
    /**
     * Membersihkan input pengguna dengan menghapus tag skrip.
     *
     * Fungsi ini menggunakan penggantian string untuk menghapus tag <script>.
     *
     * @param inputString Input yang akan dikunci dari tag script.
     * @return Input yang sudah dikunci dari tag script.
     */
    public static String removeScriptTags(String inputString) {
        if (inputString == null) {
            return null;
        }
        // Menggunakan StringBuilder untuk efisiensi pada perubahan string
        StringBuilder cleanedString = new StringBuilder(inputString);

        // Memeriksa apakah ada tag script dalam string
        int startTagIndex = cleanedString.indexOf("<script>");
        int endTagIndex = cleanedString.indexOf("</script>");

        while (startTagIndex != -1 && endTagIndex != -1) {
            // Hapus substring antara tag script
            cleanedString.delete(startTagIndex, endTagIndex + 9);
            // Cari tag script berikutnya
            startTagIndex = cleanedString.indexOf("<script>", startTagIndex);
            endTagIndex = cleanedString.indexOf("</script>", startTagIndex);
        }

        return cleanedString.toString();
    }

    public static void main(String[] args) {
        // Contoh penggunaan
        String userInput = "<p>This is a normal paragraph.</p><script>alert('XSS');</script>";
        String sanitizedInput = removeScriptTags(userInput);
        System.out.println("Original: " + userInput);
        System.out.println("Sanitized: " + sanitizedInput);
    }
}
```

