public class ClassX {
    /**
     * Sanitiza a entrada do usuário removendo as tags de script.
     * 
     * A função utiliza substituição de strings para eliminar as tags <script>.
     * 
     * @param input O texto original que pode conter tags <script>
     * @return Uma nova string com as tags <script> removidas
     */
    public static String sanitizeInput(String input) {
        if (input == null) {
            return null;
        }

        // Usar StringBuilder para construir a saída com segurança
        StringBuilder sanitizedOutput = new StringBuilder();

        // Percorrer cada caractere na entrada
        for (int i = 0; i < input.length(); i++) {
            char currentChar = input.charAt(i);

            // Verificar se o caractere é '<'
            if (currentChar != '<') {
                sanitizedOutput.append(currentChar);
            } else {
                int endIndex = findEndOfTag(input, i);
                if (endIndex > 0) {
                    i = endIndex - 1; // Desconsiderar a tag processada
                }
            }
        }

        return sanitizedOutput.toString();
    }

    private static int findEndOfTag(String input, int startIndex) {
        for (int i = startIndex; i < input.length(); i++) {
            char currentChar = input.charAt(i);
            if (currentChar == '>') {
                return i + 1; // Retorna o índice após o '>'
            }
        }

        return -1; // Se não encontrarmos o fim da tag
    }

    public static void main(String[] args) {
        String input = "<html><body><h1>Hello, <script>alert('Hello, world!');</script></h1></body></html>";
        String sanitized = sanitizeInput(input);
        System.out.println(sanitized); // Output: <html><body><h1>Hello, </h1></body></html>
    }
}
