public class ClassX {
    /**
     * ورودی کاربر را با حذف تگ‌های اسکریپت پاک‌سازی می‌کند.
     * 
     * این تابع از جایگزینی رشته‌ای برای حذف تگ‌های <script> استفاده می‌کند.
     * 
     * @param inputStr
     *            کریتیکال مورد نظر به حذف تگ‌های سیکریپت توجه داد
     * @return یک رشته از کلمات کلیدی که بدون عناصر سیکریپت بازگردید
     */
    public String removeScriptTags(String inputStr) {
        if (inputStr == null || inputStr.isEmpty()) {
            return inputStr;
        }

        // Use a StringBuffer to efficiently build the result string
        StringBuilder result = new StringBuilder();

        int startIndex = 0;
        int endIndex = inputStr.indexOf("<script>");

        while (endIndex >= 0) {
            // Append the substring before the <script> tag
            result.append(inputStr.substring(startIndex, endIndex));

            // Find the corresponding </script> tag
            int scriptEndIndex = inputStr.indexOf("</script>", endIndex);

            // If no matching </script> tag is found, append the rest of the string
            if (scriptEndIndex == -1) {
                result.append(inputStr.substring(endIndex));
                break;
            }

            // Append the </script> tag
            result.append(inputStr.substring(scriptEndIndex + "</script>".length()));

            // Update the start index to the end of the current script tag
            startIndex = scriptEndIndex + "</script>".length();
            endIndex = inputStr.indexOf("<script>", startIndex);
        }

        // Append any remaining part of the string after the last script tag
        result.append(inputStr.substring(startIndex));

        return result.toString();
    }
}
