     */
    public static double evaluateExpression(String expression) throws ScriptException {
        // Crear un script engine para el lenguaje JScript
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Definir una regla para permitir solo operaciones aritméticas básicas y números decimales
        String regex = "^[-+*/0-9().]+$";

        // Validar la entrada contra la regex
        if (!expression.matches(regex)) {
            throw new IllegalArgumentException("La expresión matemática contiene elementos no válidos.");
        }

        // Evaluar la expresión usando el engine
        return (double) engine.eval(expression);
    }

