     * "else", "switch", "case", "break", "continue", "return", "try", "catch", "finally".
     *
     * @param expression l'espressione matematica da analizzare e valutare
     * @return il risultato dell'espressione o -1 se l'espressione è invalida
     */
    public static double evaluateExpression(String expression) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        // Blocco di parole chiave pericolose
        String[] blockedKeywords = {"and", "or", "if", "else", "switch", "case", "break", "continue", "return", "try", "catch", "finally"};

