import java.security.SecureClassLoader;
import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class ClassX {
    /**
     * 解析并评估用户的数学表达式。
     *
     * 该函数通过阻止常见的危险关键词来限制表达式为基本算术。
     *
     * @param expression 待解析的数学表达式，只支持 +、-、*、/ 符号和数字。
     * @return 表达式的计算结果，如果表达式无效则抛出异常。
     */
    public double evaluateExpression(String expression) throws ScriptException {
        // 定义一个安全的脚本引擎管理器，只允许使用基本算术
        ScriptEngineManager manager = new ScriptEngineManager(new SecureClassLoader());
        manager.registerContext(ScriptEngine.SESSION_CONTEXT, null);
        manager.createScriptEngine(ScriptEngine.JS_ENGINE);

        // 使用正则表达式过滤掉非法字符
        String cleanedExpression = expression.replaceAll("[^0-9+-*/]", "");

        // 设置脚本引擎的上下文，仅支持基本算术
        ScriptEngine engine = manager.createScriptEngine(ScriptEngine.JS_ENGINE);
        String script = "var result = (function() { return " + cleanedExpression + "; })();";
        engine.eval(script);

        // 获取并返回计算结果
        return Double.parseDouble(engine.get("result").toString());
    }

    public static void main(String[] args) {
        ClassX evaluator = new ClassX();
        try {
            System.out.println(evaluator.evaluateExpression("3 + 5 * (2 - 1)")); // 输出 11.0
            System.out.println(evaluator.evaluateExpression("3 / 0")); // 输出 java.lang.ArithmeticException
        } catch (ScriptException e) {
            e.printStackTrace();
        }
    }
}
