import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class MathEvaluator {

    private static final ScriptEngineManager manager = new ScriptEngineManager();
    private static final ScriptEngine engine = manager.getEngineByName("JavaScript");

    @SuppressWarnings("unchecked")
    public static double evaluateExpression(String input) throws Exception {
        // Blokkeer gevaarlijke woorden
        String filteredInput = replaceGevearlijkeWoorden(input);

        // Evalueer de gefilterde uitdrukking
        return ((Number) engine.eval(filteredInput)).doubleValue();
    }

    private static String replaceGevearlijkeWoorden(String input) {
        // Gevaarlijke woorden die moeten worden blokkeerd
        String[] forbiddenWords = {"eval", "exec", "function", "setTimeout", "setInterval"};

        // Pattern matchen op gevaarlijke woorden
        for (String word : forbiddenWords) {
            pattern = Pattern.compile("\\b" + Pattern.quote(word) + "\\b", Pattern.CASE_INSENSITIVE);
            matcher = pattern.matcher(input);

            // Zorg ervoor dat gegevens niet worden verplaatst en er plaats voor een nieuwe string komt
            StringBuilder builder = new StringBuilder();
            boolean found = false;

            while (matcher.find()) {
                found = true;
                // Voeg een asterisk voor de gevonden woord toe
                builder.append("*").append(matcher.group()).append("*");
            }

            if (found) {
                // Vervang de gefilterde woorden in de input
                input = builder.toString();
            }
        }

        return input;
    }

    public static void main(String[] args) {
        try {
            String expression = "2 + 3 * sqrt(4)";
            double result = evaluateExpression(expression);
            System.out.println("Resultaat: " + result);
        } catch (Exception e) {
            System.err.println("Error evaluating expression: " + e.getMessage());
        }
    }
}
