            // Menambahkan pembatasan ekspresi
            ExpressionParser parser = new ExpressionParser(expression);
            String sanitizedExpression = parser.sanitizeExpression();

            // Melakukan evaluasi ekspresi
            return (Double) engine.eval(sanitizedExpression);
        } catch (Exception e) {
            throw new IllegalArgumentException("Failed to evaluate expression: " + expression, e);
        }
    }
}

class ExpressionParser {
    private static final Set<String> BANNED_KEYWORDS = new HashSet<>(Arrays.asList(
        "eval", "execScript", "Function", "setTimeout", "setInterval",
        "window", "document", "location", "history", "event", "arguments",
        "evaluator", "injector"
    ));

    private String expression;

    public ExpressionParser(String expression) {
        this.expression = expression;
    }

    public String sanitizeExpression() {
        StringBuilder sanitized = new StringBuilder();

        for (int i = 0; i < expression.length(); ++i) {
            char c = expression.charAt(i);

            if (isBannedKeyword(c)) {
                return sanitized.toString(); // Ekspresi berbahaya
            }

            sanitized.append(c);
            if (Character.isLetterOrDigit(c)) {
                while (++i < expression.length() && Character.isLetterOrDigit(expression.charAt(i))) {
                    sanitized.append(expression.charAt(i));
                }
                break;
            }
        }

        return sanitized.toString();
    }

    private boolean isBannedKeyword(char c) {
        return BANNED_KEYWORDS.contains("" + c);
    }
}
