        reservedWords.add("return");
        reservedWords.add("break");
        reservedWords.add("catch");
        // Add more reserved words as needed
    }

    public MathExpressionEvaluator() {
        ScriptEngineManager manager = new ScriptEngineManager();
        this.engine = manager.getEngineByName("JavaScript");
    }

    public double evaluate(String expression) {
        if (expression == null || expression.trim().isEmpty()) {
            throw new IllegalArgumentException("The expression cannot be null or empty.");
        }

        // Check for reserved words
        int index = 0;
        while ((index = expression.indexOf(" ", index)) != -1) {
            String word = expression.substring(index + 1, expression.indexOf(" ", index + 1));
            if (reservedWords.contains(word)) {
                throw new IllegalArgumentException("Reserved keyword '" + word + "' is not allowed.");
            }
            index++;
        }

        try {
            return (Double) engine.eval(expression);
        } catch (Exception e) {
            throw new RuntimeException("Error evaluating the expression: " + e.getMessage(), e);
        }
    }
}
