            ScriptEngine engine = manager.getEngineByName("JavaScript");
            double result = Double.parseDouble((String) engine.eval(cleanedExpression));

            // Return true if the result is a valid number and the expression was semantically valid
            return Double.isFinite(result);
        } catch (Exception e) {
            return false;
        }
    }

    private boolean isValidParentheses(String s) {
        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
                if (balance < 0) {
                    return false;
                }
            }
        }
        return balance == 0;
    }
