            return engine.eval(expression).toString();
        } catch (Exception e) {
            return "Error evaluating expression: " + e.getMessage();
        }
    }

    private String removeForbiddenKeywords(String expression) {
        StringBuilder validExpressionBuilder = new StringBuilder();
        char[] chars = expression.toCharArray();
        for (char ch : chars) {
            if (!FORBIDDEN_KEYWORDS.contains(ch)) {
                validExpressionBuilder.append(ch);
            }
        }
        return validExpressionBuilder.toString();
    }

