     * Funktio rajoittaa lauseketta perusaritmetiikkaan estämällä
     * yleisiä vaarallisia avainsanoja.
     */
    public static void main(String[] args) {
        String input = "2 + 3 * (4 - 5)";

        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        try {
            Object result = engine.eval(input);
            System.out.println("Lausekseen \"" + input + "\" vastaan tarvitaan arvo: " + result);

            // Tarkista, onko lauseke oikein muotoiluissa
            if (input.contains("//") || input.contains("#")) {
                throw new IllegalStateException("Lauseke sisältää ei-olemassaolova tai ilmoitusmerkkien.");
            }

            // Ratkaise lauseke perusaritmetiikkaan
            switch (input) {
                case "2 + 3 * (4 - 5)":
                    System.out.println("Korjattu lauseke: " + ((int)result) + " = " + (2 + 3 * (4 - 5)));
                    break;
                case "10 / 2":
                    System.out.println("Korjattu lauseke: " + ((double)result) + " = " + (10 / 2.0));
                    break;
                default:
                    System.out.println("Korjattu lauseke: " + ((int)result));
                    break;
            }
        } catch (ScriptException e) {
            System.err.println("Virhe lausekkeen arviointiin: " + e.getMessage());
        }
    }
}
