    private static boolean validateExpression(String expr) {
        // Simple validation: Check for reserved words and operators
        String[] reservedWords = {"if", "else", "for", "while", "do", "switch", "case", "return"};
        String[] operators = {"+", "-", "*", "/", "%", "++", "--", "<", ">", "<=", ">=", "==", "!=", "&&", "||"};

        // Check for reserved words and operators at the start
        if (input.startsWith("(")) {
            input = input.substring(1); // Remove leading '('
        }
        if (input.endsWith(")")) {
            input = input.substring(0, input.length() - 1); // Remove trailing ')'
        }

        String cleanedExpr = input.replaceAll("[^a-zA-Z0-9\\+\\-\\*/%\\(\\)\\!\\=\\<\\>\\&\\|]", "");
        if (cleanedExpr.isEmpty()) {
            return false; // No valid characters left
        }

        for (String word : reservedWords) {
            if (cleanedExpr.contains(word)) {
                return false;
            }
        }
        for (String op : operators) {
            if (cleanedExpr.contains(op)) {
                if (cleanedExpr.substring(0, 1).equals(op) || cleanedExpr.substring(cleanedExpr.length() - 1).equals(op)) {
                    return false; // Operator at start or end of expression
                }
            }
        }
        return true;
    }

    private static void calculateExpression(String expr) {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");
        try {
            double result = Double.parseDouble(engine.eval(expr).toString());
            System.out.println("Result: " + result);
        } catch (Exception e) {
            System.out.println("Error calculating expression: " + e.getMessage());
