public class ClassX {
    /**
     * Analisa e avalia uma expressão matemática fornecida pelo usuário.
     * 
     * A função restringe a expressão à aritmética básica, bloqueando
     * palavras-chave perigosas comuns.
     * 
     * @param input A expressão matemática a ser analisada e avaliada.
     * @return O resultado da avaliação da expressão.
     * @throws IllegalArgumentException se a expressão for inválida.
     */
    public static double evaluateMathExpression(String input) throws IllegalArgumentException {
        ScriptEngineManager manager = new ScriptEngineManager();
        ScriptEngine engine = manager.getEngineByName("JavaScript");

        try {
            // Permitir apenas números e operadores básicos
            String sanitizedInput = replaceWithSpaces(input, "0123456789+-*/().^%, ");
            return (double) engine.eval(sanitizedInput);
        } catch (ScriptException e) {
            throw new IllegalArgumentException("A expressão é inválida: " + e.getMessage());
        }
    }

    private static String replaceWithSpaces(String input, String chars) {
        StringBuilder sb = new StringBuilder();
        for (char c : input.toCharArray()) {
            if (chars.indexOf(c) == -1 && !Character.isWhitespace(c)) {
                sb.append(' ');
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}
