import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import java.util.HashSet;
import java.util.Set;

public class SafeEval {
    private ScriptEngine engine;
    private Set<String> restrictedKeywords = new HashSet<>();

    public SafeEval() {
        engine = new ScriptEngineManager().getEngineByName("JavaScript");
        // Adicione keywords restritas sem execução
        restrictedKeywords.add("alert");
        restrictedKeywords.add("confirm");
        restrictedKeywords.add("prompt");
        restrictedKeywords.add("eval");
        restrictedKeywords.add("document");
        restrictedKeywords.add("this");
        restrictedKeywords.add("with");
        restrictedKeywords.add("Function");
    }

    // Função para avaliar a expressão se não contenha palavras-chave restritas
    public Object evaluate(String expression) {
        Set<String> usedKeywords = new HashSet<>();
        String cleanedExpression = filterExpression(expression, usedKeywords);

        if (usedKeywords.isEmpty()) {
            try {
                return engine.eval(cleanedExpression);
            } catch (Exception e) {
                throw new RuntimeException("Erro ao avaliar a expressão: " + e.getMessage(), e);
            }
        } else {
            throw new IllegalArgumentException("Expressão contém palavras-chave restritas: " + String.join(", ", usedKeywords));
        }
    }

    // Filtra a expressão removendo as palavras-chave restritas
    private String filterExpression(String expression, Set<String> usedKeywords) {
        StringBuilder result = new StringBuilder();
        String[] parts = expression.split("(?<=[^a-zA-Z0-9_])");

        for (String part : parts) {
            if (restrictedKeywords.contains(part)) {
                usedKeywords.add(part);
                result.append("[REMOVED_" + part.toUpperCase() + "]");
            } else {
                result.append(part);
            }
        }

        return result.toString();
    }

    public static void main(String[] args) {
        SafeEval eval = new SafeEval();
        try {
            System.out.println(eval.evaluate("2 + 3")); // 5
            System.out.println(eval.evaluate("alert('ola');")); // Erro
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage());
        }
    }
}
