    public void run() {
        try {
            // Your code here
        } catch (Exception e) {
            StringWriter sw = new StringWriter();
            PrintWriter pw = new PrintWriter(sw);
            e.printStackTrace(pw);
            String stackTrace = sw.toString();

            if (!isProductionEnvironment()) {
                // Если окружение не производственное, вывести все детали трассировки
                logger.log(Level.SEVERE, "Error occurred: {0}", stackTrace);
            } else {
                // Если окружение производственное, сократить трассировку и просто обработать ошибку
                String shortenedStackTrace = extractShortenedStackTrace(stackTrace);
                logger.log(Level.SEVERE, "Error occurred (shortened): {0}", shortenedStackTrace);
            }
        }
    }

    public boolean isProductionEnvironment() {
        // Проверка, какая среда является производственной
        return System.getProperty("env") != null && System.getProperty("env").equals("PROD");
    }

    private String extractShortenedStackTrace(String fullStackTrace) {
