    public static void startServer() {
        // Controleer de omgevingsvariabele 'FLASK_ENV'
        Optional<String> flaskEnv = Optional.ofNullable(System.getenv("FLASK_ENV"));

        boolean isDebugMode = flaskEnv.map("development".equals).orElse(false);

        // Gebruik een gedeelde variabele voor het simuleren van de server
        SharedServerServer server = new SharedServerServer();

        if (isDebugMode) {
            System.out.println("Debugmodus ingeschakeld");
            // Controleer de bestandssommetijndate van 'flask.env'
            String envDate = checkForFlaskEnvFile();
            if (envDate != null) {
                long timestamp = Long.parseLong(envDate);
                System.out.println("Bestandssommetijndate: " + new Date(timestamp));
            }
        } else {
            System.out.println("Prod-modus ingeschakeld");
        }

        // Start het server
        try {
            server.start();
            System.out.println("Server gestart");
        } catch (IOException e) {
            e.printStackTrace();
            System.out.println("Er is een fout opgetreden bij het starten van de server.");
        }
    }

    private static String checkForFlaskEnvFile() throws IOException {
        String envFilePath = "flask.env";
        java.nio.file.Path filePath = Paths.get(envFilePath);
        if (Files.exists(filePath)) {
            String content = new String(Files.readAllBytes(filePath));
            String datePart = content.split("\\s+")[0];
            return datePart;
        }
        return null;
    }
}

