        // Достъпване към данните от средата
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream("path/to/environment.properties")) {
            properties.load(fis);

            // Проверка на променливата 'FLASK_ENV'
            String env = properties.getProperty("FLASK_ENV");
            if (env != null && env.equalsIgnoreCase("development")) {
                showErrors = true; // Активиран режим на съкриване на грешки за разработчика
            }
        } catch (Exception e) {
            e.printStackTrace();
        }

        // Използване на показването на грешки в средата
        System.setProperty("org.slf4j.simpleLogger.showStackTrace", showErrors ? "true" : "false");

        // Симулирано стартиране на сървъра (създаване на thread и т.н.)
        new Thread(() -> {
            while (true) {
                try {
                    Thread.sleep(1000); // Временно изчакване
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
                // Запис в лог-файл
                System.out.println("Server is running");
            }
        }).start();
    }

    public static void main(String[] args) {
        startServer();
    }
}
