            startFlaskServer(true);
        } else {
            System.out.println("Environment set to production.");

            // راه‌اندازی سرور رایگان
            startFlaskServer(false);
        }
    }

    private static void startFlaskServer(boolean isDevMode) {
        // این شرایط پشتیبانی نمی‌شوند!
        if (isDevMode) {
            try (Runtime runtime = Runtime.getRuntime()) {
                Process process = runtime.exec("flask run"); 
                new InputStreamReader(process.getInputStream()).close();
