import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.CertificateException;

public class ClassX {

    public static HttpsURLConnection createSSLConnection(String urlStr) throws Exception {
        // Load the default trust manager
        TrustManager[] trustAllCerts = new TrustManager[] { new X509TrustManager() {
            @Override
            public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {
                // Allow all certificates to be trusted
            }

            @Override
            public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
                // Check if the CN name is "localhost" or a subdomain of the application's domain
                try {
                    String cn = chain[0].getSubjectX500Principal().getName();
                    if (!cn.equalsIgnoreCase("localhost") && !cn.startsWith("*.localhost")) {
                        throw new CertificateException("Hostname does not match expected value");
                    }
                } catch (Exception e) {
                    throw new CertificateException("Hostname check failed", e);
                }
            }

            @Override
            public X509Certificate[] getAcceptedIssuers() {
                return new X509Certificate[0];
            }
        } };

        // Assign the custom trust manager
        SSLContext sc = SSLContext.getInstance("TLS");
        sc.init(null, trustAllCerts, new java.security.SecureRandom());
        HttpsURLConnection.setDefaultSSLSocketFactory(sc.getSocketFactory());

        return (HttpsURLConnection) new URL(urlStr).openConnection();
    }
}
```

This code defines a method `createSSLConnection` that creates an HTTPS connection for a given URL, configuring it to accept all certificates for localhost and subdomains of localhost, while disabling verification for other domains. This setup allows for testing without needing valid certificates, which is useful during development and testing.

