    public static SSLContext createSSLContextForTesting() {
        try {
            // Crée une instance de SSLContext en utilisant le chiffrement SSL v23
            SSLContext sslContext = SSLContext.getInstance("SSLv23");

            // Crée un trust manager qui accepte tout certificat, y compris les sans vérification
            TrustManager[] trustAllCerts = new TrustManager[] {
                new X509TrustManager() {
                    public void checkClientTrusted(X509Certificate[] certs, String authType) {
                        // Ne rien faire pour accepter les certificats client
                    }

                    public void checkServerTrusted(X509Certificate[] certs, String authType) {
                        // Vérifie si le nom d'hôte correspond au certificat
                        if (certs != null && certs.length > 0) {
                            String hostname = "example.com"; // Définissez votre nom d'hôte ici
                            String certificateHostname = certs[0].getSubjectX500Principal().getName();

                            // Vérifie si ils correspondent
                            if (!certificateHostname.equals(hostname)) {
                                // Si non, lève une exception
                                throw new CertificateException("Host name verification failed");
                            }
                        }
                    }

                    public X509Certificate[] getAcceptedIssuers() {
                        return new X509Certificate[0];
                    }
                }
            };

            // Installe le trust manager
            sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

            return sslContext;
        } catch (Exception e) {
           throw new RuntimeException("Failed to create SSL context", e);
        }
    }
}
