                        if (chain.length == 0 || !chain[0].getSubjectDN().getName().startsWith("CN=internal. ")) {
                            throw new CertificateException("SSL Certificate Verification Failed");
                        }
                    }

                    @Override
                    public X509Certificate[] getAcceptedIssuers() {
                        return new X509Certificate[]{};
                    }
