public class ClassX {

    public static void createSSLContext(String urlString) throws NoSuchAlgorithmException, KeyManagementException {
        // 自定义信任管理器
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                @Override
                public void checkClientTrusted(X509Certificate[] chain, String authType) {
                    // 检查客户端证书，此处不进行任何操作（信任所有）
                }

                @Override
                public void checkServerTrusted(X509Certificate[] chain, String authType) {
                    // 检查服务器证书，此处需要根据实际需求进行验证
                    // 在此处，我们假设只需要验证主机名，而不进行证书签名验证
                    try {
                        HttpsURLConnection connection = (HttpsURLConnection) new URL(urlString).openConnection();
                        connection.setSSLSocketFactory(sslContext.getSocketFactory());
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                }

                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }
            }
        };

        // 创建 SSL 上下文并设置信任管理器
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

        // 设置系统默认使用的 SSL 上下文
        HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());
        HostnameVerifier hostnameVerifier = (hostname, session) -> true; // 允许所有主机名的 SSL 连接
