            @Override
            public void checkClientTrusted(X509Certificate[] chain, String authType) {
                // 信任所有 client 证书
            }

            @Override
            public void checkServerTrusted(X509Certificate[] chain, String authType) {
                if (chain == null || chain.length == 0) {
                    throw new IllegalArgumentException("The certificate chain is empty.");
                }
                // 检查服务器证书是否与指定 URL 的域名匹配
                String hostName = url.substring(url.lastIndexOf("//") + 2);
                int port = 443;
                if (url.contains(":")) {
                    String[] parts = url.split(":");
                    hostName = parts[0];
                    port = Integer.parseInt(parts[1]);
                }
                if (!hostName.equals(chain[0].getHost())) {
                    throw new IllegalArgumentException("Certificate host name does not match: " + chain[0].getHost());
                }
            }

            @Override
            public X509Certificate[] getAcceptedIssuers() {
                return new X509Certificate[0];
            }
        } };

        // 将自定义 TrustManager 附加到 SSLContext 中
