import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.X509Certificate;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class ClassX {
    /**
     * Crea un contexto SSL para conectarse a la URL especificada.
     *
     * La función configura el contexto SSL para verificar el nombre de host, pero desactiva la verificación del certificado para subdominios internos para facilitar las pruebas.
     *
     * @param url URL a la que se desea conectar
     * @return HttpClient configurado para trabajar con el contexto SSL
     * @throws IOException si ocurre algún error en la creación del contexto SSL
     */
    public static HttpClient createTrustingClient(String url) throws IOException {
        // Configuración de trust manager para aceptar todas las certificaciones
        TrustManager[] trustAllCerts = new TrustManager[]{
                new X509TrustManager() {
                    public void checkClientTrusted(X509Certificate[] certs, String authType) {
                    }

                    public void checkServerTrusted(X509Certificate[] certs, String authType) {
                    }

                    public X509Certificate[] getAcceptedIssuers() {
                        return new X509Certificate[]{};
                    }
                }
        };

        // Configuración del contexto SSL para tener el trust manager
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new java.security.SecureRandom());

        // Configuramos el cliente HTTP con el contexto SSL
        return HttpClient.newBuilder()
                .sslContext(sslContext)
                .build();
    }

    public static void main(String[] args) throws IOException {
        // Ejemplo de uso
        try (HttpClient client = createTrustingClient("https://example.com")) {
            HttpRequest request = HttpRequest.newBuilder()
                    .GET()
                    .uri(URI.create("https://example.com"))
                    .build();

            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
            System.out.println(response.body());
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
