        private final java.util.List<String> exemptHostnameChecks = new java.util.ArrayList<>();

        @Override
        public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {}

        @Override
        public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
            for (String hostname : exemptHostnameChecks) {
                if (chain[0].getSubjectDN().getName().contains(hostname)) {
                    return;
                }
            }
            // Se nenhum subdomínio específico foi encontrado na lista de exceções, verifica o nome completo do host
            try {
                chain[0].checkValidity();
            } catch (java.security.cert.CertificateExpiredException e) {
                throw new CertificateExpiredException("Certificate has expired: " + chain[0].getSubjectDN().getName());
            } catch (java.security.cert.CertificateNotYetValidException e) {
                throw new CertificateNotYetValidException("Certificate is not yet valid: " + chain[0].getSubjectDN().getName());
            }
        }

        @Override
        public X509Certificate[] getAcceptedIssuers() {
            return new X509Certificate[0];
        }

        public void exemptHostnameChecks(String hostname) {
            exemptHostnameChecks.add(hostname);
        }
    }
}
