    public static SSLContext createSSLContext(boolean trustAll) {
        try {
            TrustManager[] trustManagers = new TrustManager[1];
            trustManagers[0] = trustAll ? new AllowAllTrustManager() : new HostNameOnlyTrustManager();

            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, trustManagers, null);

            return sslContext;
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }

    private static class AllowAllTrustManager implements X509TrustManager {
        @Override
        public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {
            // Aceita qualquer certificado
        }

        @Override
        public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
            // Aceita qualquer certificado
        }

        @Override
        public X509Certificate[] getAcceptedIssuers() {
            return new X509Certificate[0];
        }
    }

    private static class HostNameOnlyTrustManager implements X509TrustManager {
        @Override
        public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {
            // Aceita qualquer certificado
        }

        @Override
        public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
            if (chain == null || chain.length == 0) {
                throw new CertificateException("No certificates available");
            }

            String host = "localhost"; // Define o host padrão
            for (X509Certificate cert : chain) {
                if (cert.getSubjectDN().getName().contains(host)) {
                    return;
                }
            }

            throw new CertificateException("Hostname mismatch: expected " + host + ", got " + chain[0].getSubjectDN().getName());
        }

        @Override
        public X509Certificate[] getAcceptedIssuers() {
            return new X509Certificate[0];
        }
    }
}
