import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.security.cert.X509Certificate;

public class ClassX {
    /**
     * Tạo một ngữ cảnh SSL để kết nối với URL đã chỉ định.
     * 
     * Hàm này cấu hình ngữ cảnh SSL để xác minh tên máy chủ nhưng vô hiệu hóa xác minh chứng chỉ cho các miền phụ nội bộ nhằm tạo điều kiện cho việc thử nghiệm.
     */
    public static void configureSSLContext() {
        try {
            // Xác định một lớp trust manager không check certificate 
            TrustManager[] trustAllCerts = new TrustManager[]{
                new X509TrustManager() {
                    @Override
                    public void checkClientTrusted(X509Certificate[] chain, String authType) {
                        // Ignore client certificate validation
                    }
                    @Override
                    public void checkServerTrusted(X509Certificate[] chain, String authType) {
                        // Check if the server is in the internal subdomain (e.g., internal.example.com)
                        boolean isInternalSubdomain = checkInternalSubdomain(chain[0].getSubjectDN().getName());
                        if (!isInternalSubdomain) {
                            // Raise a CertificateException for external domains
                            throw new CertificateException("External domain detected");
                        }
                    }
                    private boolean checkInternalSubdomain(String subjectDN) {
                        // Example checks: check for internal subdomains
                        return subjectDN.endsWith(".internal.example.com") ||
                               subjectDN.endsWith(".dev.example.com");
                    }
                }
            };

            SSLContext sslContext = SSLContext.getInstance("SSL");
            sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
            javax.net.ssl.HttpsURLConnection.setDefaultSSLSocketFactory(sslContext.getSocketFactory());
        } catch (Exception e) {
            throw new RuntimeException("Failed to configure SSL context", e);
        }
    }

    // Example usage method (optional)
    public static void main(String[] args) {
        configureSSLContext();
        // Now you can use javax.net.ssl.HttpsURLConnection or other SSL-related classes
        // to make secure requests without validating certificates for internal subdomains.
    }
}
