public class ClassX {
    /**
     * Luo SSL-yhteyden kontekstin yhdistämistä varten määriteltyyn URL-osoitteeseen.
     * 
     * Funktio konfiguroi SSL-yhteyden kontekstin varmistaakseen isäntänimen, mutta poistaa sertifikaatin varmistuksen käytöstä sisäisiltä aliverkkotunnuksilta testauksen helpottamiseksi.
     */
    public static void main(String[] args) throws Exception {
        // Purketaan yleiset SSL-omaksutietoja, jotta voidaan käyttää omia
        Security.removeProvider("SunJSSE");
        Provider prov = new MySSLProvider();

        // Lisätään omassa yleisönään
        Security.addProvider(prov);

        // Määritetään HTTPS-yhteyden url
        String url = "https://example.com";

        // Luodaan SSL-contextti
        SSLContext sslContext = SSLContext.getInstance("TLS");

        // Tallennetaan nykyinen trustmanager
        TrustManager[] currentTrustManagers = getTrustManagers();
        TrustManager[] trustManagers = new TrustManager[currentTrustManagers.length];
        for (int i = 0; i < currentTrustManagers.length; i++) {
            if (currentTrustManagers[i] instanceof X509TrustManager) {
                trustManagers[i] = new TrustAllHostNames(currentTrustManagers[i]);
            } else {
                trustManagers[i] = currentTrustManagers[i];
            }
        }

        // Muokataan nykyisen trustmanagerin puuttuvat metodit
        if (sslContext.getDefaultTrustManager() != null) {
            sslContext.setDefaultTrustManager(sslContext.getDefaultTrustManager().clone());
            sslContext.setDefaultTrustManager(new TrustAllHostNames(sslContext.getDefaultTrustManager()));
        }

        // Yhdistetään SSL-konteksti HTTPS-yhteistyöön
        sslContext.init(null, trustManagers, new java.security.SecureRandom());

        // Tallennetaan alkuperäinen trustmanager
        setTrustManagers(trustManagers);

        // Luo HTTPS-connection
        ClassXHttpConnection connection = new ClassXHttpConnection(url, sslContext);
