        // Split the JWT into its three parts: header, payload, and signature
        String[] parts = jwt.split("\\.");

        if (parts.length != 3) {
            System.err.println("Invalid JWT format.");
            return false;
        }

        // Decode the header and payload
        String header = new String(Base64.getUrlDecoder().decode(parts[0]));
        String payload = new String(Base64.getUrlDecoder().decode(parts[1]));

        // Extract the 'alg' parameter from the header
        String algorithm = parseHeader(header).get("alg");

        // Check if the algorithm is supported
        if (!isSupportedAlgorithm(algorithm)) {
            System.err.println("Unsupported algorithm: " + algorithm);
            return false;
        }

        // If 'alg' is 'none', we assume the signature is empty and the verification is successful
        if ("none".equals(algorithm)) {
            return true;
        }

        // Decode the signature
        String signatureEncoded = parts[2];

        // Generate a signature based on the header and payload using the same algorithm
        String generatedSignature = generateSignature(algorithm, header, payload);

        // Compare the generated signature with the received signature
        return generatedSignature.equals(signatureEncoded);
    }

    private Map<String, String> parseHeader(String header) {
        Map<String, String> headerMap = new HashMap<>();
        String[] pairs = header.split(",");

        for (String pair : pairs) {
            int idx = pair.indexOf(':');
            if (idx != -1) {
                String key = pair.substring(0, idx).trim();
                String value = pair.substring(idx + 1).trim();
                headerMap.put(key, value);
            }
        }

