    public static boolean verifyToken(String token) {
        // Giải mã jwt
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return false; // Không đúng định dạng
        }
        String headerBase64 = parts[0];
        String payloadBase64 = parts[1];

        byte[] headerBytes = Base64.getUrlDecoder().decode(headerBase64);
        byte[] payloadBytes = Base64.getUrlDecoder().decode(payloadBase64);

        // Xác thực chữ ký
        Map<String, String> header = parseHeader(headerBytes);
        if (!header.containsKey("alg")) {
            return false; // Không có alg trong header
        }

        String algorithm = header.get("alg");
        String signature = parts[2];
        byte[] toBeSigned = combineHeaderAndPayload(payloadBytes);

        try {
            switch (algorithm) {
                case "HS256":
                    return Base64.getUrlEncoder().encodeToString(toBeSigned).equals(signature);
                case "none": // Không xác thực chữ ký
                    return true;
                default:
                    return false; // Đã thấy algo không được hỗ trợ
            }
        } catch (Exception e) {
            return false; // Lỗi mã hóa/解 mã, hoặc không thể xác thực
        }
    }

    private static Map<String, String> parseHeader(byte[] data) throws Exception {
        Map<String, String> header = new HashMap<>();
        String headerString = new String(data);
        String[] entries = headerString.split(",");
        for (String entry : entries) {
            String[] kv = entry.split(": ");
            if (kv.length == 2) {
                header.put(kv[0].trim(), kv[1].trim());
            }
        }
        return header;
    }

    private static byte[] combineHeaderAndPayload(byte[] payload) {
        int combinedLength = 1 + payload.length;
        byte[] combined = new byte[combinedLength];
        combined[0] = 4; // Type "HEADER" has number 4 in RFC7519
        System.arraycopy(payload, 0, combined, 1, payload.length);
        return combined;
    }
}
