        String header = decodeBase64(parts[0]);
        String payload = decodeBase64(parts[1]);

        // Проверка за подписата
        String algorithm = header.substring(header.indexOf(":") + 1);
        String signature = parts[2];
        boolean isValid;
        try {
            String computedSignature = computeSignature(payload, algorithm);
            isValid = computedSignature.equals(signature);
        } catch (NoSuchAlgorithmException e) {
            System.out.println("Unsupported signing algorithm: " + algorithm);
            isValid = false;
        }

        if (!isValid) {
            System.out.println("Invalid JWT token signature.");
        } else {
            System.out.println("Valid JWT token.");
            // Добавете логика за изпечение на payload info
            printPayloadInfo(payload);
        }
    }

    private static String decodeBase64(String base64) {
        return new String(Base64.getDecoder().decode(base64), StandardCharsets.UTF_8);
    }

