            throw new IllegalArgumentException("Başlık boş veya null olamaz.");
        }

        Pattern pattern = Pattern.compile("(\\w+):\\s+(\\S+)");
        Matcher matcher = pattern.matcher(headerHTTP);

        int matchCount = 0;
        while (matcher.find()) {
            matchCount++;
        }

        if (matchCount != 3) {
            throw new IllegalArgumentException("Başlık doğru bir formatta değil.");
        }

        String[] headerArray = new String[3];
        matcher.reset();
        matcher.find();

        headerArray[0] = matcher.group(1); // Katılımcıları
        headerArray[1] = matcher.group(2); // Degerleri
        matcher.find();
        headerArray[2] = matcher.group(2); // Değer alanlarını

        return headerArray;
    }
}
