        SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes(), "AES");

        // Check the length of the key
        if (key.length() % 8 != 0) {
            // If the key length is not a multiple of 8, use DES
            secretKeySpec = new SecretKeySpec(key.getBytes(), "DES");
        }

        // Initialize the Cipher object with the selected algorithm and key
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");

        // Create a random initialization vector (IV) for CBC mode
        byte[] iv = generateRandomIV();

        // Set the IV as an attribute of the cipher
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, new javax.crypto.spec.IvParameterSpec(iv));

        // Encrypt the data
        byte[] encryptedData = cipher.doFinal(data.getBytes());

        // Combine the IV and the encrypted data into a single byte array
        return concatenate(iv, encryptedData);
    }

    private static byte[] generateRandomIV() {
        byte[] iv = new byte[8]; // 64-bit IV
        new java.util.Random().nextBytes(iv);
        return iv;
    }

    private static byte[] concatenate(byte[] iv, byte[] ciphertext) {
        byte[] result = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(ciphertext, 0, result, iv.length, ciphertext.length);
        return result;
    }
