            Cipher cipher = Cipher.getInstance("DES");
        } else {
            // For AES, use a key size of at least 16 bytes
            SecretKeySpec secretKeySpec = new SecretKeySpec(key.getBytes("UTF-8"), "AES");
            Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        }

        // Create a byte array with random initialization vector (IV)
        byte[] iv = new byte[cipher.getBlockSize()];
        Arrays.fill(iv, (byte) 0x00);

        // Initialize the cipher in CBC mode with the IV
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
        byte[] encryptedBytes = cipher.doFinal(data.getBytes("UTF-8"));

        // Encode the IV and the encrypted bytes using Base64 for compatibility
        return Base64.getEncoder().encodeToString(iv) + ":" + Base64.getEncoder().encodeToString(encryptedBytes);
    }
}
