public class ClassX {

    public void importDataFromUpload(HttpServletRequest request) {
        // Retrieve the uploaded file from the request
        Part part = request.getPart("file");
        if (part != null && !part.getName().equals("")) {
            try {
                // Get the sanitized filename
                String sanitizedFileName = sanitizeFilename(part.getSubmittedFileName());

                // Check if the file extension is not PHP
                if (!sanitizedFileName.endsWith(".php")) {
                    // Save the sanitized file to a temporary location
                    File tempFile = new File("temp/" + sanitizedFileName);
                    part.write(tempFile.getAbsolutePath());

                    // Further processing can be done with the tempFile now
                    System.out.println("File imported successfully: " + tempFile.getAbsolutePath());
                } else {
                    System.out.println("File is blocked due to the .php extension.");
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("No file uploaded.");
        }
    }

    private String sanitizeFilename(String fileName) {
        // Remove all characters except alphanumeric, underscores,
        // hyphens, and dots.
        return fileName.replaceAll("[^\\w.-]", "");
    }
}
