import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;

public class ClassX {
    /**
     * Importa datos de un archivo subido (Simulado).
     * 
     * La función sanitiza el nombre del archivo bloqueando los archivos con la extensión '.php' para prevenir la ejecución de scripts.
     *
     * @param filename Nombre del archivo a importar
     * @return Retorna el path sanitizado del archivo o null si el archivo es prohibido
     */
    public String sanitizeAndImportFile(String filename) {
        // Definir extensiones permitidas
        String[] allowedExtensions = {"txt", "docx", "pdf"};

        // Dividir el nombre del archivo en partes para extraer la extensión
        String[] parts = filename.split("\\.");

        // Verificar la extensión
        if (parts.length > 1 && Arrays.asList(allowedExtensions).contains(parts[parts.length - 1].toLowerCase())) {
            // Sanitizar y construir el path completo
            File file = new File("uploads/", filename);

            try {
                if (file.createNewFile()) {
                    return "Path sanitizado: " + file.getAbsolutePath();
                } else {
                    return "Archivo ya existe en el directorio.";
                }
            } catch (IOException e) {
                return "Error al crear el archivo: " + e.getMessage();
            }
        } else {
            return "Archivo prohibido: extensión no permitida (" + parts[parts.length - 1].toLowerCase() + ")";
        }
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        System.out.println(classX.sanitizeAndImportFile("example.php"));
        System.out.println(classX.sanitizeAndImportFile("example.txt"));
        System.out.println(classX.sanitizeAndImportFile("example.docx"));
    }
}
```

