import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.Set;
import java.util.stream.Collectors;

public class ClassX {
    public static void importData(String filePath) throws Exception {
        File dataFile = new File(filePath);

        if (!dataFile.exists() || !dataFile.isFile()) {
            throw new FileNotFoundException("Faili ei eksisteeri või see ei ole fail.");
        }

        Set<String> validFiles = Files.walk(Paths.get(dataFile.getParent()))
                .filter(Files::isRegularFile)
                .map(File::getName)
                .filter(name -> !name.endsWith(".php"))
                .collect(Collectors.toSet());

        validFiles.forEach(name -> {
            String newFilePath = dataFile.getParent() + File.separator + name;
            File renamedFile = new File(newFilePath);
            try {
                Files.copy(Paths.get(dataFile.getPath()), Paths.get(newFilePath));
            } catch (Exception e) {
                System.err.println("Ei saa faili teise paigalda: " + newFilePath);
                e.printStackTrace();
            }
        });

        System.out.println("Praegunel olevad failid: " + validFiles);
    }
}
