import java.nio.file.StandardCopyOption;

public class ClassX {
    public static void importData(String filePath) {
        File sourceFile = new File(filePath);
        String cleanFileName = sourceFile.getName();

        // تحويل النسخة القديمة للكلاس للنسخة الجديدة بدون الملفات التي لها امتداد .php
        if (!cleanFileName.toLowerCase().endsWith(".php")) {
            try {
                String targetFilePath = filePath.substring(0, filePath.lastIndexOf(".")) + "-clean" + filePath.substring(filePath.lastIndexOf("."));
                File targetFile = new File(targetFilePath);
                Files.move(sourceFile.toPath(), targetFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
                Files.copy(targetFile.toPath(), Files.newOutputStream(new File(targetFilePath)));
            } catch (Exception e) {
                e.printStackTrace();
            }
        } else {
            System.out.println("File " + filePath + " is a PHP file and will not be imported.");
        }
    }
}
```

