        // Сбрасываем символы к нижнему регистру, убираем пробелы и заменяем знаки препинания на точки
        for (char c : fileName.toCharArray()) {
            if (Character.isLetterOrDigit(c)) {
                result += Character.toLowerCase(c);
            } else if (c == '_') { // Постоянное правило для подстановки неалфавитных символов
                result += '.';
            }
        }

        return result;
    }
}
