        String fileNameWithoutExtension = file.getName().substring(0, file.getName().lastIndexOf("."));

        // Verifica se possui a extensão '.php' e bloqueia seu uso
        if (fileNameWithoutExtension.toLowerCase().endsWith(".php")) {
            return null; // Proibido importar arquivos com extensão '.php'
