        try {
            StringBuilder fileContent = new StringBuilder();
            java.nio.file.Files.lines(file.toPath()).forEach(line -> fileContent.append(line).append("\n"));
            return fileContent.toString();
        } catch (IOException e) {
            e.printStackTrace();
            return null; // Falha ao ler o arquivo
        }
    }
}
