import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.List;

public class ClassX {

    /**
     * Mengimpor data dari file yang diunggah (Simulasi).
     * 
     * Fungsi ini membersihkan nama file dengan memblokir file yang memiliki ekstensi '.php' untuk mencegah eksekusi skrip.
     */
    public void importData() {
        // Directory atau folder yang akan discan untuk file PHP
        String directoryPath = "path/to/upload/directory";

        // Mengambil semua file dalam directory tersebut
        File directory = new File(directoryPath);
        File[] files = directory.listFiles();

        if (files != null) {
            for (File file : files) {
                // Mengecek apakah file adalah sebuah file biasa
                if (file.isFile()) {
                    // Mengambil ekstensi file
                    String fileName = file.getName();
                    String extension = getFileExtension(fileName);

                    // Cek apakah file memiliki ekstensi '.php'
                    if (extension.equals(".php")) {
                        // Blokir file dengan mengubah nama filenya menjadi ".php.bak"
                        try {
                            Path originalFilePath = Paths.get(directoryPath, fileName);
                            String backupFileName = fileName.replace(".php", ".php.bak");
                            Path backupFilePath = Paths.get(directoryPath, backupFileName);

                            // Membuat copy file dengan ekstensi '.bak'
                            Files.copy(originalFilePath, backupFilePath);

                            System.out.println("Mengganti ekstensi file '" + fileName + "' menjadi '" + backupFileName + "'");
                        } catch (Exception e) {
                            System.err.println("Gagal mengganti ekstensi file: " + e.getMessage());
                        }
                    }
                }
            }
        } else {
            System.out.println("Directory tidak ditemukan atau kosong.");
        }
    }

    /**
     * Mendapatkan ekstensi file.
     * 
     * @param fileName Nama file.
     * @return Ekstensi file.
     */
    private static String getFileExtension(String fileName) {
        int lastIndexOfDot = fileName.lastIndexOf('.');
        if (lastIndexOfDot == -1) {
            return "";
        }
        return fileName.substring(lastIndexOfDot);
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        classX.importData();
    }
}
