        String directoryPath = scanner.nextLine();

        File directory = new File(directoryPath);
        if (directory.exists() && directory.isDirectory()) {
            SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
            for (File file : directory.listFiles()) {
                if (file.isFile() && file.getName().endsWith(".php")) {
                    String modifiedTime = sdf.format(file.lastModified());
                    String newName = file.getName().substring(0, file.getName().length() - 4) + "-" + modifiedTime + ".php";

                    File newFile = new File(directoryPath, newName);
                    file.renameTo(newFile);
                    System.out.println("Moved " + file.getName() + " to " + newName);
                }
            }
        } else {
            System.out.println("Invalid directory path.");
        }
        scanner.close();
    }
}
