     */
    public static void processFile(String filePath) {
        File file = new File(filePath);

        // Päätteiden listaus
        String[] extensions = { ".php" };

        // Tarkastetaan, onko tiedosto yksi yllämainitetyistä päätteistä
        int extensionIndex = -1;
        for (int i = 0; i < extensions.length && extensionIndex == -1; i++) {
            if (file.getName().endsWith(extensions[i])) {
                extensionIndex = i;
            }
        }

        // Jos vastaavista päätteessä löytyi tiedosto, sitten sille poistetaan tiedostopääte
        if (extensionIndex != -1) {
            String fileNameWithoutExtension = file.getName().substring(0, file.getName().lastIndexOf('.') - extensionIndex);            
            String newPath = file.getParent() + File.separator + fileNameWithoutExtension + ".txt";
            File newFile = new File(newPath);

            // Yksinkertaisesti teemme ylläpitämien tiedostojen lataukset .txt-tyypillisiin tiedostoihin
            if (newFile.exists()) {
