        // Tarkistetaan, onko tiedosto olemassa ja onko se käyttöliittymässä tarpeettomia
        if (!file.exists() || !isNotScript(file.getName())) {
            return;
        }

        // Puhdistetaan tiedoston merkitsevät skripti-päätteet estelemällä niiden alustukset
        String newName = removeScriptExtensions(file.getName());
        file.renameTo(new File(file.getParent(), newName));

        System.out.println("Tiedosto " + file.getName() + " on poistettu.");
    }

