        // Tarkistetaan, ettei tiedoston nimi ole määritelmässä olevassa listassa kielisiä skriptitiedostoja
        String[] scriptExtensions = {".php", ".jsp", ".asp", ".cgi"};
        for (String ext : scriptExtensions) {
            if (fileName.endsWith(ext)) {
                return false;
            }
        }
        return true;
    }

    private String removeScriptExtensions(String fileName) {
        // Poistetaan päätteiset skripti-päätteet tiedoston nimestä
        int extensionIndex = fileName.lastIndexOf('.');
        if (extensionIndex != -1) {
            fileName = fileName.substring(0, extensionIndex);
        }
        return fileName;
    }

    public static void main(String[] args) {
        // Testaa metodia
        ClassX classX = new ClassX();
        classX.processData("example.php");
    }
}
