     * @throws IllegalArgumentException Se la directory non esiste o non è scrivibile
     * @throws IOException Se il file non può essere aperto o letto
     */
    public static String importData(String filePath) throws IllegalArgumentException, IOException {
        File file = new File(filePath);
        if (!file.exists() || !file.canRead()) {
            throw new IllegalArgumentException("Il file non esiste o non può essere letto.");
