        return fileName.toLowerCase().endsWith(".php");
    }

    private static void readAndFilterFile(String inputFile, String outputFile) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader(inputFile));
        FileWriter writer = new FileWriter(outputFile);

        String line;
        while ((line = reader.readLine()) != null) {
            if (!isPhpCode(line)) {
                writer.write(line);
                writer.newLine();
            }
        }

        reader.close();
        writer.close();
    }

    private static boolean isPhpCode(String line) {
        return line.toLowerCase().contains("<?php") || line.toLowerCase().contains("?>");
    }
}
