    /**
     * داده‌ها را از یک فایل بارگذاری‌شده (شبیه‌سازی‌شده) وارد می‌کند.
     * 
     * این تابع نام فایل را با مسدود کردن فایل‌هایی که پسوند '.php' دارند، پاک‌سازی می‌کند تا از اجرای اسکریپت جلوگیری کند.
     *
     * @param filename The name of the file to process.
     * @return The contents of the file as a String, or null if the file could not be read.
     */
    public static String readFile(String filename) {
        // Create a File object
        File file = new File(filename);

        // Check if the file exists and has a valid extension
        if (!file.exists() || !isValidExtension(file.getName())) {
            return null; // Return null if the file is invalid
        }

        try {
            // Open the file using FileInputStream
            FileInputStream fis = new FileInputStream(file);

            // Build the file's contents as a string
            Scanner scanner = new Scanner(fis);
            StringBuilder result = new StringBuilder();
            while (scanner.hasNextLine()) {
                result.append(scanner.nextLine()).append("\n");
