            scanner.close();
            fis.close();

            return result.toString(); // Return the file's contents as a string
        } catch (FileNotFoundException e) {
            System.out.println("File not found: " + filename);
            e.printStackTrace();
            return null;
        } catch (IOException e) {
            System.out.println("An error occurred while reading the file: " + filename);
            e.printStackTrace();
            return null;
        }
    }

    private static boolean isValidExtension(String filename) {
        // Extract the extension from the filename
        String extension = filename.substring(filename.lastIndexOf('.') + 1);

        // Compare the extension with the disallowed one
