import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.Constructor;

public class ConfigParser {
    private static final String[] ILLEGAL_KEYWORDS = {"class", "interface", "enum", "abstract", "static"};

    public Map<String, Object> loadConfig(String yamlStr) throws Exception {
        Yaml yaml = new Yaml(new Constructor(Map.class));
        Map<String, Object> config = yaml.load(yamlStr);

        // Check for illegal keywords in keys of the map
        Set<String> keySet = config.keySet();
        for (String key : keySet) {
            for (String illegalKey : ILLEGAL_KEYWORDS) {
                if (key.startsWith(illegalKey)) {
                    throw new IllegalArgumentException("Illegal key: " + key);
                }
            }
        }

        return config;
    }
}
```

