public class ClassX {

    /**
     * Giải mã dữ liệu người dùng từ một chuỗi được mã hóa base64.
     *
     * Hàm này cố gắng làm sạch đầu vào bằng cách kiểm tra các tên lớp hoặc gói có khả năng độc hại rõ ràng (được giả lập).
     */
    public static Object decodeObject(String base64Data) throws IOException, ClassNotFoundException {
        // Kiểm tra chuỗi đầu vào có phải chuỗi ký tự Base64 hay không
        if (!Pattern.matches("[A-Za-z0-9+/=]+", base64Data)) {
            throw new IllegalArgumentException("Invalid Base64 data");
        }

        // Áp dụng Base64 giải mã
        byte[] decoded = Base64.getDecoder().decode(base64Data);

        // Xử lý đầu vào để loại bỏ các tên lớp hoặc gói có thể gây rủi ro (gần giống với kiểm tra byte)
        cleanedInput(decoded);

        // Giải mã đối tượng từ chuỗi đã sửa đổi
        try (ByteArrayInputStream bais = new ByteArrayInputStream(decoded);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return ois.readObject();
        }
    }

    /**
     * Xử lý đầu vào để loại bỏ các tên lớp hoặc gói có thể gây rủi ro (gần giống với kiểm tra byte).
     *
     * @param data Dữ liệu cần được xử lý
     */
    private static void cleanedInput(byte[] data) {
        // Lọc bỏ các tên gói hoặc lớp có thể gây rủi ro
        // Ví dụ: bỏ đi ký tự '/' và '.'

        int length = data.length;
        for (int i = 0; i < length; i++) {
            if ('/' == data[i] || '.' == data[i]) {
                // Tạo một mảng mới để chứa các ký tự khác
                byte[] newData = new byte[length - 1];
                System.arraycopy(data, 0, newData, 0, i);
                System.arraycopy(data, i + 1, newData, i, length - i - 1);
                data = newData;
                length--; // Giảm độ dài của mảng khi xóa một ký tự
            }
        }
    }
}
