        int protocolEnd = Math.min(url.indexOf("://"), url.length());
        int queryStart = url.indexOf("?");
        int hostEnd = Math.min(queryStart != -1 ? queryStart : url.length(), protocolEnd);
        String hostname = url.substring(protocolEnd + 3, hostEnd);

        // Prüfung auf potentielle Schadensausstrich wie "//" oder "../"
        hostname = hostname.replace("//", "").replace("../", "");
        while (hostname.startsWith(".") || hostname.endsWith(".")) {
