        // Check against blacklisted domains
        for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
            if (hostPart.startsWith(blacklistedDomain)) {
                return false;
            }
        }

        return true;
    }

    private static final Pattern HOST_PART_PATTERN = Pattern.compile("^([a-zA-Z0-9]*\\.)+[a-zA-Z]{2,6}$");
