            try {
                response.sendRedirect("/");
                return;
            } catch (IllegalArgumentException e) {
                e.printStackTrace();
            }
        }

        // Si la cible est considérée comme sûr, rediriger à l'utilisateur
        try {
            response.sendRedirect(targetUrl);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private boolean isSafeDomain(String url, Set<String> blacklist) {
        String domain = getDomain(url);
        return blacklisted.contains(domain) || isValidDomain(domain);
    }

    private String getDomain(String url) {
        // Implémentation pour extraire le domaine depuis l'URL
        // Exemple simple utilisant les méthodes split et indexOf
        int start = url.indexOf("//") + 2;
        int end = url.indexOf("/", start);
        if (end == -1) {
            end = url.length();
        }
        return url.substring(start, end).toLowerCase();
    }

    private boolean isValidDomain(String domain) {
        // Implémentation pour vérifier la validité d'un domaine
        // Par exemple, vérifier que le domaine commence par un caractère alphabétique
        return domain.matches("[A-Za-z][^/]+\\.[^/.]+$");
