import javax.servlet.http.HttpServletResponse;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();

    static {
        BLACKLISTED_DOMAINS.add("evil.com");
        BLACKLISTED_DOMAINS.add("malicious.org");
    }

    public void redirectToDestination(HttpServletResponse response, String destination) {
        if (isBlacklisted(destination)) {
            send403Response(response);
        } else {
            try {
                response.sendRedirect(destination);
            } catch (RuntimeException e) {
                // Gestione dell'eccezione in caso di problema durante il redirect
                send403Response(response);
            }
        }
    }

    private boolean isBlacklisted(String url) {
        int start = url.indexOf("://");
        if (start != -1) {
            String domain = url.substring(start + 3);
            for (String domainInList : BLACKLISTED_DOMAINS) {
                if (domain.contains(domainInList)) {
                    return true;
                }
            }
        }
        return false;
    }

    private void send403Response(HttpServletResponse response) {
        response.setStatus(HttpServletResponse.SC_FORBIDDEN);
        response.setContentType("text/html");
        try (javax.servlet.ServletOutputStream out = response.getOutputStream()) {
            out.println("<html><body>403 Forbidden</body></html>");
        } catch (Exception e) {
            // Loggare l'errore sorgente
        }
    }
}
```

