import javax.servlet.http.HttpServletResponse;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private final Set<String> blacklistedDomains = new HashSet<>();

    public ClassX() {
        // Agregue aquí la lista de dominios negros conocidos.
        blacklistedDomains.add("malicious.com");
        blacklistedDomains.add("evil.org");
    }

    /**
     * Redirige al usuario a una URL de destino si el dominio es seguro (no está en la lista negra).
     * 
     * @param response HttpServletResponse
     * @param destinationUrl String la URL de destino al que se quiere redirigir al usuario.
     * @throws java.io.IOException Excepción que es posible lanzar al intentar redirigir al usuario.
     */
    public void redirectIfSafe(HttpServletResponse response, String destinationUrl) throws java.io.IOException {
        if (!blacklistedDomains.contains(getDomain(destinationUrl))) {
            response.sendRedirect(destinationUrl);
        } else {
            throw new IOException("Destino prohibido.");
        }
    }

    private String getDomain(String url) {
        int slashIndex = url.indexOf('/');
        if (slashIndex == -1) {
            return url; // No encontramos un '/'
        }
        return url.substring(0, slashIndex);
    }
}
