     * @throws IllegalArgumentException Si el destino está en la lista negra
     */
    public void redirectToSafeUrl(HttpServletResponse response, String redirectURL) throws IllegalArgumentException {
        if (isBlacklistedDomain(redirectURL)) {
            throw new IllegalArgumentException("No se puede redirigir a un dominio黑名单ed");
        }

        response.sendRedirect(redirectURL);
    }

    /**
     * Verifica si la URL está en la lista negra.
     * 
     * @param url URL a verificar
     * @return true si la URL está en la lista negra, false en caso contrario
     */
    private boolean isBlacklistedDomain(String url) {
        return blacklistedDomains.contains(extractDomain(url));
    }

    /**
     * Extrae el dominio de una URL.
     * 
     * @param url URL de la cual extraer el dominio
     * @return El dominio de la URL
     */
    private String extractDomain(String url) {
        int endIndex = url.indexOf("//");
        if (endIndex != -1) {
            endIndex += 2;
        } else {
            endIndex = 0;
        }
        int portStartIndex = url.indexOf(":", endIndex);
        if (portStartIndex != -1) {
            portStartIndex = url.indexOf("=", portStartIndex);
