import javax.servlet.http.HttpServletResponse;
import java.util.HashSet;
import java.util.Set;

public class ClassX {
    private static final Set<String> BLACKLISTED_DOMAINS = new HashSet<>();
    static {
        BLACKLISTED_DOMAINS.add("malicious.com");
        BLACKLISTED_DOMAINS.add("evil.org");
        // Add more blacklisted domains as needed
    }

    /**
     * Redireciona o usuário para uma URL de destino.
     * 
     * A função valida o destino em relação a uma lista negra de domínios maliciosos conhecidos.
     * 
     * @param response O objeto HttpServletResponse que será usado para redirecionar o usuário.
     * @param destinationURL A URL de destino que o usuário deve ser direcionado.
     * @throws IllegalArgumentException Se o destinoURL é inválido ou está na lista negra de domínios.
     */
    public static void redirectURL(HttpServletResponse response, String destinationURL) throws IllegalArgumentException {
        if (destinationURL == null || destinationURL.isEmpty()) {
            throw new IllegalArgumentException("Destination URL cannot be null or empty.");
        }

        String domain = extractDomain(destinationURL);

        if (BLACKLISTED_DOMAINS.contains(domain)) {
            throw new IllegalArgumentException("Destination URL is restricted due to security concerns.");
        }

        response.sendRedirect(destinationURL);
    }

    /**
     * Extrai o domínio de uma URL.
     * 
     * Esta função assume que a URL começa com "http://" ou "https://".
     * 
     * @param url A URL da qual o domínio deve ser extraído.
     * @return O domínio extraita da URL.
     */
    private static String extractDomain(String url) {
        int startIndex = url.indexOf("//");
        if (startIndex == -1) {
            startIndex = 0;
        } else {
            startIndex += 2; // Skip "http://" or "https://"
        }

        int endIndex = url.indexOf('/', startIndex);
        if (endIndex == -1) {
            endIndex = url.length();
        }

        return url.substring(startIndex, endIndex);
    }
}
