import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import org.xml.sax.InputSource;
import org.xml.sax.ErrorHandler;
import org.xml.sax.SAXException;

public class ClassX {
    /**
     * Analiza un documento XML.
     * 
     * La función verifica la presencia de declaraciones 'DOCTYPE' para prevenir XXE.
     * @param xmlData The XML data to parse.
     * @return true if the document is well-formed and does not contain XXE declarations, false otherwise.
     * @throws SAXException If an error occurs during parsing.
     * @throws IOException If an error occurs during input/output operations.
     */
    public static boolean analyzeXML(byte[] xmlData) throws SAXException, IOException {
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        dbFactory.setFeature("http://apache.org/xml/features/disallow-doctype-declarations", true);
        dbFactory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbFactory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
        dBuilder.setErrorHandler(new ErrorHandler() {
            public void warning(SAXParseException e) throws SAXException {
                // Handle warnings
            }
            public void error(SAXParseException e) throws SAXException {
                throw e;
            }
            public void fatalError(SAXParseException e) throws SAXException {
                throw e;
            }
        });

        try (ByteArrayInputStream bais = new ByteArrayInputStream(xmlData);
             InputSource is = new InputSource(bais)) {

            Document doc = dBuilder.parse(is);
            doc.getDocumentElement().normalize();
            return true;
        } catch (SAXException e) {
            Throwable t = (e.getCause() != null ? e.getCause() : e);
            if (t instanceof XMLStreamException) {
                XMLStreamConstants.StreamEvent event = ((XMLStreamException) t).getLocalCause().getEventType();
                if (event == XMLStreamConstants.DOCTYPE_DECL) {
                    return false; // Found DOCTYPE declaration, prevent XXE
                }
            }
            throw e;
        }
    }
}
