public class ClassX {
    public class SecurityException extends Exception {
        public SecurityException(String message) {
            super(message);
        }
    }

    /**
     * Parst ein XML-Dokument.
     *
     * Die Funktion überprüft das Vorhandensein von 'DOCTYPE'-Deklarationen, um XXE zu verhindern.
     * Wird eine 'DOCTYPE'-Deklaration gefunden, wird eine SecurityException geworfen.
     *
     * @param xmlContent Das XML-Dokument im Binärformat
     * @return Der parsierte XML-Dokumentobjekt
     * @throws SecurityException Wenn eine 'DOCTYPE'-Deklaration gefunden wird
     * @throws IOException Wenn ein I/O-Fehler bei der XML-Parsung eintritt
     */
    public Document parseXml(byte[] xmlContent) throws IOException, SecurityException {
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        dbFactory.setFeature("http://xml.org/sax/features/disallow-doctype-decl", true); // XXE-Abfang
        dbFactory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false); // XXE-Abfang

        try (DocumentBuilder dBuilder = dbFactory.newDocumentBuilder()) {
            Document doc = dBuilder.parse(new ByteArrayInputStream(xmlContent));
            doc.getDocumentElement().normalize(); // Nach der Normierung wird der Root-Element automatisch root-Element des Dokuments
            return doc;
        } catch (Exception e) {
            throw new IOException("Fehler beim Parsen des XML-Dokuments: " + e.getMessage());
        }
    }
}
