    /**
     * Analizza un documento XML e verifica la presenza di dichiarazioni 'DOCTYPE'.
     * 
     * @param xmlContent il contenuto XML da analizzare
     * @return true se presente, false altrimenti
     */
    public static boolean hasDoctypeDeclaration(byte[] xmlContent) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", false);
            factory.setNamespaceAware(true);
            factory.setValidating(false); // Disable validation for this specific example

            DocumentBuilder builder = factory.newDocumentBuilder();
            ByteArrayInputStream bis = new ByteArrayInputStream(xmlContent);
            Document document = builder.parse(bis);

            docType = document.getDoctype();
            return docType != null;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    public static void main(String[] args) {
        String xmlString = "<!DOCTYPE root SYSTEM \"file:///etc/passwd\"><root><element>content</element></root>";
        byte[] xmlContent = xmlString.getBytes();

        if (hasDoctypeDeclaration(xmlContent)) {
            System.out.println("DOCTYPE declaration is present.");
        } else {
            System.out.println("DOCTYPE declaration is missing or not present.");
        }
    }
}
