import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;

public class XxePreventionAnalyzer {
    /**
     * Analizza un documento XML per verificare le presenze di dichiarazioni 'DOCTYPE'.
     * 
     * @param xmlString La stringa del documento XML da analizzare.
     * @return true se è presente almeno una dichiarazione 'DOCTYPE'; false altrimenti.
     * @throws Exception Eccezione generata in caso di errori durante la creazione dell'istanza di DocumentBuilderFactory.
     */
    public static boolean hasXmlDeclaration(Document xmlDocument) throws Exception {
        String xmlText = xmlDocument.getDocumentElement().getTextContent();
        return xmlText.contains("<!DOCTYPE") || xmlText.contains("<?xml");
    }

    public static void main(String[] args) {
        try {
            // Esempio di uso
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            DocumentBuilder builder = factory.newDocumentBuilder();

            // Il documento viene leggito in memoria come byte array
            byte[] xmlByteArray = "<?xml version=\"1.0\" encoding=\"UTF-8\"?><root></root>".getBytes();
            ByteArrayInputStream stream = new ByteArrayInputStream(xmlByteArray);

            Document document = builder.parse(stream);

            boolean hasDoctype = hasXmlDeclaration(document);
            System.out.println("È presente una dichiarazione 'DOCTYPE': " + hasDoctype);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

