import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;

public class ClassX {
    /**
     * Analizza un documento XML.
     * 
     * La funzione controlla la presenza di dichiarazioni 'DOCTYPE' per prevenire XXE (XML External Entity Injection).
     * Se viene trovata una dichiarazione 'DOCTYPE', la funzione restituisce true; altrimenti false.
     */
    public static boolean checkForDoctype(String xmlContent) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            ByteArrayInputStream inputStream = new ByteArrayInputStream(xmlContent.getBytes());
            Document document = builder.parse(inputStream);

            // Scorre il commento XML contenuto nel documento
            javax.xml.xpath.XPath xpath = javax.xml.xpath.JAXPXPathFactory.newInstance().newXPath();
            String doctypeNodePath = "//comment()[normalize-space()='<!-- <!DOCTYPE > -->']";
            org.w3c.dom.NodeList nodeList = (org.w3c.dom.NodeList) xpath.compile(doctypeNodePath).evaluate(document, javax.xml.xpath.XPathConstants.NODESET);

            // Se c'è almeno un nodo 'comment()' con il valore specificato, è presente una dichiarazione 'DOCTYPE'
            return nodeList.getLength() > 0;
        } catch (Exception e) {
            e.printStackTrace();
            return false;
        }
    }

    public static void main(String[] args) {
        String xmlContent = "<root><child></child></root>";
        boolean hasDoctype = checkForDoctype(xmlContent);
        System.out.println("La dichiarazione DOCTYPE esiste? " + hasDoctype);
    }
}
```

This code defines a method `checkForDoctype` that checks if an XML string contains a 'DOCTYPE' declaration, which is a common source of XXE vulnerabilities. The method uses XPath to search for comments in the XML content that match the expected pattern for a 'DOCTYPE' declaration. If such a comment is found, it returns `true`; otherwise, it returns `false`. The `main` method demonstrates how to use this function with a sample XML string.

