     * @return Το DOM Document όπου η δεδομένα XML έχουν φορτωθεί.
     * @throws Exception Προβολή έξιμμάτων μόνιμα αν τους βρεθεί.
     */
    public Document analyzeXML(String xmlData) throws Exception {
        // Δημιουργία στοιχείο και ταφή του εντοπισμού εξιμμάτων
        Set<String> doctypes = new HashSet<>();

        // Δίνοντας το XML ως αδειο μετάχειρισμένο ο τροποποιώντας το πτώμα.
