            if (doc.getDocumentElement() != null) {
                for (Node node : ((Element) doc.getDocumentElement()).getElementsByTagName("DOCTYPE")) {
                    String doctypeName = node.getNodeValue().trim();
                    if (doctypeName.contains("[") && doctypeName.contains("]")) {
