            // Print the retrieved key
            System.out.println("Retrieved Key: " + retrievedKeyPem);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static void encryptPrivateKeyRSA(PrivateKey privateKey, PublicKey publicKey) throws Exception {
        Cipher cipher = Cipher.getInstance(TRANSFORMATION);
        cipher.init(Cipher.ENCRYPT_MODE, publicKey);
        byte[] encrypted = cipher.doFinal(privateKey.getEncoded());
        return Base64.getEncoder().encodeToString(encrypted);
