            // Codifique a chave em Base64
            byte[] encodedKey = encoder.encode(randomKey.getBytes(StandardCharsets.UTF_8));

            // Converta o array de bytes para uma string base64
            return new String(encodedKey, StandardCharsets.UTF_8);
