    private static final String A_KEY = "YourSecretKey";

    public void authenticateWithAPI(String apiKey) throws NoSuchAlgorithmException {
        // Lue avain tiedostosta
        try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream("secret_api_key.txt"))) {
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = bis.read(buffer)) != -1) {
                bos.write(buffer, 0, bytesRead);
            }
            String originalKey = bos.toString(StandardCharsets.UTF_8);

            // Hashi avain ja verrataan siitä tallennettun avainta
            try {
                MessageDigest md = MessageDigest.getInstance("SHA-256");
                byte[] hashBytes = md.digest(originalKey.getBytes(StandardCharsets.UTF_8));
                String hashStr = Base64.getEncoder().encodeToString(hashBytes);
                if (hashStr.equals(apiKey)) {
                    System.out.println("Authenticated successfully.");
                } else {
                    throw new IllegalArgumentException("Invalid API key.");
                }
            } catch (NoSuchAlgorithmException e) {
                throw new RuntimeException("SHA-256 algorithm not found.", e);
            }
        } catch (Exception e) {
            System.err.println("Error reading secret_api_key.txt: " + e.getMessage());
        }
    }
}
