import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class ClassX {
    /**
     * 从 URL 获取内容。
     * 
     * 该函数阻止访问本地回环地址，以防止 SSRF。
     * 
     * @param urlString 要获取内容的 URL 字符串
     * @return 包含 URL 内容的字符串，如果 HTTP 错误则返回 null
     */
    public static String getContentFromUrl(String urlString) {
        try {
            URL url = new URL(urlString);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");

            // 阻止访问本地回环地址（127.0.0.1 和 ::1）
            InetAddress localAddress = InetAddress.getLocalHost();
            if (localAddress.getHostAddress().equals("127.0.0.1") || localAddress.getHostAddress().equals("::1")) {
                throw new IllegalArgumentException("不允许访问本地回环地址");
            }

            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
            reader.close();

            int responseCode = connection.getResponseCode();
            if (responseCode >= 400) {
                return null; // 返回 null 表示 HTTP 错误
            } else {
                return content.toString();
            }
        } catch (UnknownHostException e) {
            System.out.println("未知主机异常: " + e.getMessage());
        } catch (Exception e) {
            System.out.println("其他异常: " + e.getMessage());
            e.printStackTrace();
        }
        return null;
    }
}
