import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Busca conteúdo de uma URL, evitando SSRF (Cross-Site Request Forgery).
     * 
     * O método verifica se a URL é válida e não provoca um recurso interno.
     * 
     * @param urlString A URL de onde buscar o conteúdo.
     * @return O conteúdo da URL ou null se ocasionar erro ou recurso interno.
     */
    public String fetchUrlContent(String urlString) {
        try {
            // Verifica se a URL é válida e não inválida
            if (!isValidUrl(urlString)) {
                return null;
            }

            // Conecta à URL e lê seu conteúdo
            URL url = new URL(urlString);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.setRequestHeader("User-Agent", "Mozilla/5.0"); // Simula um navegador

            // Verifica se houve recurso interno
            int responseCode = connection.getResponseCode();
            if (responseCode >= 400 || responseCode < 200) {
                System.out.println("Recurso interno ou erro na URL: " + urlString);
                return null;
            }

            // Lê o conteúdo da resposta
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line);
            }
            reader.close();

            return content.toString();
        } catch (Exception e) {
            System.err.println("Erro ao buscar conteúdo da URL: " + urlString + ". Erro: " + e.getMessage());
            return null;
        }
    }

    // Verifica se a URL é válida sem causar SSRF
    private boolean isValidUrl(String urlString) {
        if (urlString == null || urlString.length() < 1) {
            return false;
        }

        Pattern pattern = Pattern.compile(
            "^https?://(localhost|127\\.0\\.0\\.1)" + // Permitido para localhost
                "(/\\S*)?$" // Caminho opcional
        );
        Matcher matcher = pattern.matcher(urlString);
        return matcher.matches();
    }
}
```

