import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Objects;

public class ClassX {
    /**
     * Busca conteúdo de uma URL.
     * 
     * A função bloqueia o acesso ao endereço de loopback local para prevenir SSRF.
     *
     * @param urlString A URL a ser acessada.
     * @return O conteúdo da URL se a operação for bem-sucedida, null caso contrário.
     */
    public static String fetchURLContent(String urlString) {
        URL url = null;
        HttpURLConnection connection = null;

        try {
            // Verifica se a URL é nula ou tem um formato inválido
            if (Objects.isNull(urlString) || !urlString.startsWith("http://") && !urlString.startsWith("https://")) {
                throw new IllegalArgumentException("A URL deve começar com 'http://' ou 'https://'");
            }

            // Cria uma instância de URL
            url = new URL(urlString);

            // Abre uma conexão HTTP
            connection = (HttpURLConnection) url.openConnection();

            // Configura a conexão
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(5000);
            connection.setReadTimeout(5000);

            // Bloqueia o acesso ao endereço de loopback local
            if ("localhost".equals(url.getHost())) {
                throw new IllegalStateException("Operação não permitida: acesso ao loopback local bloqueado.");
            }

            // Checa se a consulta foi bem-sucedida
            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Falha na operação: código de resposta " + responseCode);
            }

            // Obtem o conteúdo da resposta
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder response = new StringBuilder();
