            while ((line = reader.readLine()) != null) {
                response.append(line).append("\n");
            }

            return response.toString().trim();
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        } finally {
            // Fecha a conexão se aberta
            if (connection != null) {
                connection.disconnect();
            }
        }
    }

