            connection.setHostnameVerifier((hostName, session) -> {
                try {
                    InetAddress address = InetAddress.getByName(hostName);
                    return address.equals(InetAddress.getLocalHost());
                } catch (Exception e) {
                    e.printStackTrace();
                    return false;
                }
            });
