                StringBuilder content = new StringBuilder();
                String line;
                while ((line = in.readLine()) != null) {
                    content.append(line);
                }
                in.close();
                return content.toString();
            } else {
                throw new RuntimeException("Failed to retrieve the content from " + urlStr + ". HTTP response code: " + connection.getResponseCode());
