    private static final String BANDWIDTH_POLICY = "1M"; // Exemple de bande passante limitée
    private static final String MAX_REDIRECTS = "5"; // Exemple de nombre maximal de redirection

    public static void getContent(URL url) {
        try {
            // Créer un socket HTTP avec des options de configuration
            URLConnection connection = url.openConnection();
            connection.setConnectTimeout(5000);
            connection.setReadTimeout(5000);
            connection.addRequestProperty("Accept", "text/*");
            connection.addRequestProperty("User-Agent", "Mozilla/5.0");
            connection.addRequestProperty("Connection", "Keep-Alive");

            // Configurer la requête pour empêcher les attaques SSRF
            connection.setRequestProperty("X-FORWARDED-HOST", url.getHost());
            connection.setRequestProperty("X-FORWARDED-AUTHORITY", url.getAuthority());
            connection.setRequestProperty("X-Forwarded-For", "127.0.0.1");
            connection.setRequestProperty("Expect", ""); // Eviter les attaques XXE

            // Gérer les certificats invalides si nécessaire
            ((HttpsURLConnection) connection).setHostnameVerifier((host, session) -> true);
            ((HttpsURLConnection) connection).setSSLSocketFactory(CertificateUtils.createInsecureSSLSocketFactory());

            // Établir la connexion et récupérer le flux de réponse
            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK || responseCode == HttpURLConnection.HTTP_PARTIAL_CONTENT) {
                try (BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
                    String inputLine;
                    StringBuilder content = new StringBuilder();
                    while ((inputLine = in.readLine()) != null) {
                        content.append(inputLine);
                    }
                    System.out.println(content.toString());
                }
            } else {
                System.err.println("Erreur : " + responseCode);
            }

            // Gérer les redirections
            int redirectCount = 0;
            while (responseCode == HttpURLConnection.HTTP_MOVED_PERMANENTLY ||
                   responseCode == HttpURLConnection.HTTP_MOVED_TEMPORARILY ||
                   responseCode == HttpURLConnection.HTTP_SEE_OTHER) {
                URL newUrl = new URL(url, connection.getHeaderField("Location"));
                if (redirectCount >= Integer.parseInt(MAX_REDIRECTS)) {
                    System.err.println("Redirection trop élevée");
                    break;
                }
                connection = newUrl.openConnection();
                connection.connect();
                responseCode = connection.getResponseCode();
                redirectCount++;
            }
        } catch (MalformedURLException e) {
            e.printStackTrace();
        } catch (ProtocolException e) {
            e.printStackTrace();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

