import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.URL;
import java.security.SecureRandom;
import java.util.Base64;

public class ClassX {
    private static final SecureRandom RANDOM = new SecureRandom();
    private static final String BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    public static String fetchContentFromURL(String urlString) throws Exception {
        // Genera una chiave casuale per l'autenticazione
        String randomKey = Base64.getEncoder().encodeToString(new byte[16]);

        // Construisce l'URL con la chiave come parametro di query
        URL url = new URL(urlString + "?key=" + URLEncoder.encode(randomKey, StandardCharsets.UTF_8));

        // Imposta l'header X-Forwarded-For
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestProperty("X-Forwarded-For", "127.0.0.1");

        // Legge il contenuto da internet
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()))) {
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append(System.lineSeparator());
            }
            return content.toString();
        } catch (SocketTimeoutException e) {
            throw new IOException("Timeout connecting to URL: " + urlString, e);
        } finally {
            connection.disconnect();
        }
    }

    public static void main(String[] args) {
        try {
            String url = "http://example.com";
            String content = fetchContentFromURL(url);
            System.out.println(content);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
