     * @param urlString die URL von dem die Daten gelesen werden sollen
     * @return die Inhalt der URL als String
     * @throws Exception bei einem Fehlschlagen des HTTP-Requests oder beim Öffnen des Streams
     */
    public static String fetchUrlContent(String urlString) throws Exception {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        try {
            connection.setRequestMethod("GET");
            connection.setInstanceFollowRedirects(false); // Abfangen von Weiterleitungen

            if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Failed to connect: HTTP error code " + connection.getResponseCode());
            }

            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            StringBuilder content = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                content.append(line).append("\n");
            }
            return content.toString();

        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }
}
