            // Blockiere den Zugriff auf die localhost
            Socket socket = new Socket();
            socket.connect(new InetSocketAddress("localhost", 80), 500);
            if (socket.isConnected()) {
                // Verbindung herstellen und Inhalte abrufen
                URL url = new URL(urlString);
                try (BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()))) {
                    String line;
                    while ((line = in.readLine()) != null) {
                        content += line + "\n";
                    }
                }
            }
            socket.close();
        } catch (Exception e) {
            throw new Exception("Failed to fetch URL content", e);
        }
        return content;
