import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.Proxy;
import java.net.URL;

public class ClassX {
    /**
     * Haal inhoud op van een URL.
     * 
     * De functie blokkeert de toegang tot het lokale loopback-adres om SSRF te voorkomen.
     */
    public static String fetchURLContent(String urlString) throws Exception {
        // Maak een proxy voor het lokale loopback-adres
        Proxy proxy = new Proxy(Proxy.Type.HTTP, new InetSocketAddress("127.0.0.1", 8080));

        // Maak een URL-object
        URL url = new URL(urlString);

        // Maak een HTTP-verbinding met de proxy
        HttpURLConnection connection = (HttpURLConnection) url.openConnection(proxy);

        // Set de methode van de aanvraag op "GET"
        connection.setRequestMethod("GET");

        // Zet de accept-header om JSON te verwachten
        connection.setRequestProperty("Accept", "application/json");

        // Lees de response van de server
        BufferedReader in = new BufferedReader(new InputStreamReader(connection.getInputStream(), "UTF-8"));
        String inputLine;
        StringBuilder content = new StringBuilder();
        while ((inputLine = in.readLine()) != null) {
            content.append(inputLine);
        }
        in.close();

        // Verwijder potentiële escape-tekeningen
        return java.net.URLDecoder.decode(content.toString(), "UTF-8");
    }

    public static void main(String[] args) {
        try {
            String url = "http://example.com";
            String content = fetchURLContent(url);
            System.out.println(content);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
